interface LabelScrollingTextProps {
  label: string;
  textColor: string;
}
const LabelScrollingText: React.FC<LabelScrollingTextProps> = ({ label, textColor }) => {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [isOverflowing, setIsOverflowing] = React.useState<boolean>(false);

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const checkOverflow = () => {
      const testSpan = document.createElement('span');
      testSpan.style.visibility = 'hidden';
      testSpan.style.position = 'absolute';
      testSpan.style.whiteSpace = 'nowrap';
      testSpan.className = 'text-xs sm:text-sm font-extrabold';
      testSpan.innerText = label;
      document.body.appendChild(testSpan);
      
      const textWidth = testSpan.getBoundingClientRect().width;
      const containerWidth = container.getBoundingClientRect().width;
      
      document.body.removeChild(testSpan);
      setIsOverflowing(textWidth > containerWidth);
    };
    checkOverflow();
    const timer = setTimeout(checkOverflow, 150);
    if (typeof ResizeObserver !== 'undefined') {
      const observer = new ResizeObserver(() => {
        checkOverflow();
      });
      observer.observe(container);
      return () => {
        observer.disconnect();
        clearTimeout(timer);
      };
    }
    return () => clearTimeout(timer);
  }, [label]);

  return (
    <div ref={containerRef} className="w-full overflow-hidden relative whitespace-nowrap">
      {isOverflowing && (
        <>
          <div className="absolute left-0 top-0 bottom-0 w-3 bg-gradient-to-r from-white dark:from-zinc-900 to-transparent z-10 pointer-events-none" />
          <div className="absolute right-0 top-0 bottom-0 w-3 bg-gradient-to-l from-white dark:from-zinc-900 to-transparent z-10 pointer-events-none" />
        </>
      )}
      {isOverflowing ? (
        <div className="w-full overflow-hidden whitespace-nowrap relative">
          <div className="inline-block animate-marquee-slow whitespace-nowrap font-extrabold text-xs sm:text-sm">
            <span className={`pr-6 ${textColor}`}>{label}</span>
            <span className={`pr-6 ${textColor}`}>{label}</span>
          </div>
        </div>
      ) : (
        <span className={`text-xs sm:text-sm font-extrabold block truncate ${textColor}`} title={label}>
          {label}
        </span>
      )}
    </div>
  );
};
