  const PENDING_SYNC_KEY = 'grid_notepad_pending_sync';
  const PENDING_DELETES_KEY = 'grid_notepad_pending_deletes';
  const SETTINGS_UPDATED_AT_KEY = 'grid_notepad_settings_updated_at';
  const FIRESTORE_QUOTA_COOLDOWN_KEY = 'grid_notepad_firestore_quota_until';
  const FIRESTORE_SYNCED_DOCS_KEY = 'grid_notepad_firestore_doc_sigs';
  const FIRESTORE_SYNCED_SETTINGS_KEY = 'grid_notepad_firestore_settings_sig';

  const isFirestoreQuotaError = (err: any): boolean => {
    const code = String(err?.code || '').toLowerCase();
    const msg = String(err?.message || err || '').toLowerCase();
    return (
      code === 'resource-exhausted' ||
      msg.includes('resource-exhausted') ||
      msg.includes('quota limit exceeded') ||
      msg.includes('quota exceeded') ||
      msg.includes('daily write units')
    );
  };
  const isFirestoreTransientNetworkError = (err: any): boolean => {
    const code = String(err?.code || '').toLowerCase();
    const msg = String(err?.message || err || '').toLowerCase();
    return (
      code === 'unavailable' ||
      code === 'deadline-exceeded' ||
      code === 'aborted' ||
      msg.includes('firestore-write-timeout') ||
      msg.includes('deadline-exceeded') ||
      msg.includes('client is offline') ||
      msg.includes('failed to get document because the client is offline') ||
      msg.includes('network error')
    );
  };
  const isFirestorePausedNow = (): boolean => {
    return isFirestoreQuotaPaused() || Date.now() < firestoreTransientPauseUntilRef.current;
  };
  const tripFirestoreTransientCooldown = (contextLabel: string, err?: any) => {
    firestoreTransientPauseUntilRef.current = Date.now() + 30000;
    pauseFirestoreNetwork();
    const detail = err instanceof Error ? err.message : String(err || 'timeout');
    console.warn(`Firestore transient pause (${contextLabel}):`, detail);
    appendDebugLog(`⏳ [Firestore] Lidhja u ndërpre përkohësisht (${contextLabel}: ${detail}). Ruajtja vazhdon lokalisht, në Server & GitHub Gist.`);
  };
  const isFirestoreQuotaPaused = (): boolean => {
    try {
      const until = Number(localStorage.getItem(FIRESTORE_QUOTA_COOLDOWN_KEY) || '0');
      return Number.isFinite(until) && Date.now() < until;
    } catch (e) {
      return false;
    }
  };
  const tripFirestoreQuotaCooldown = (notifyUser = false) => {
    try {
      localStorage.setItem(FIRESTORE_QUOTA_COOLDOWN_KEY, String(Date.now() + 4 * 60 * 60 * 1000));
    } catch (e) {}
    pauseFirestoreNetwork();
    appendDebugLog('⚠️ [Firestore Quota] Kuota ditore falas e Firestore u tejkalua (rivendoset nesër). Ruajtja po vazhdon lokalisht, në Server & GitHub Gist.');
    if (notifyUser && Date.now() - lastQuotaToastAtRef.current > 60000) {
      lastQuotaToastAtRef.current = Date.now();
      showToast(t('⚠️ Kuota ditore falas e Firestore u mbush (rivendoset nesër). Të dhënat po ruhen lokalisht, në Server & GitHub Gist.', '⚠️ Firestore daily free quota reached (resets tomorrow). Data is saved locally, on Server & GitHub Gist.'));
    }
  };
  const getSyncedFirestoreDocSigs = (): Record<string, string> => {
    try {
      const raw = JSON.parse(localStorage.getItem(FIRESTORE_SYNCED_DOCS_KEY) || '{}');
      return raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
    } catch (e) {
      return {};
    }
  };
  const saveSyncedFirestoreDocSigs = (sigs: Record<string, string>) => {
    try {
      localStorage.setItem(FIRESTORE_SYNCED_DOCS_KEY, JSON.stringify(sigs));
    } catch (e) {}
  };
  const computeFirestoreDocSig = (docObj: any): string => {
    const rowCount = Array.isArray(docObj?.rows) ? docObj.rows.length : 0;
    const tagStr = Array.isArray(docObj?.tags) ? docObj.tags.map((tg: any) => String(tg)).join(',') : '';
    const headersStr = Array.isArray(docObj?.headers) ? docObj.headers.map((h: any) => String(h ?? '')).join('|') : '';
    const mediaSig = Array.isArray(docObj?.rows)
      ? docObj.rows.reduce(
          (acc: number, r: any) =>
            acc +
            (typeof r?.image === 'string' ? r.image.length : 0) +
            (typeof r?.audio === 'string' ? r.audio.length : 0) +
            (typeof r?.audioName === 'string' ? r.audioName.length : 0) +
            (typeof r?.pdf === 'string' ? r.pdf.length : 0) +
            (typeof r?.pdfName === 'string' ? r.pdfName.length : 0),
          0
        )
      : 0;
    const normTitle = String(docObj?.title || 'Pa titull').slice(0, 200);
    return `${docObj?.updatedAt || ''}|${normTitle}|${rowCount}|${docObj?.textColor || 'default'}|${tagStr}|${headersStr}|${mediaSig}`;
  };
  const computeFirestoreSettingsSig = (payload: any): string => {
    try {
      const { settingsUpdatedAt: _ignored, userId: _ignoredUid, ...rest } = payload || {};
      return JSON.stringify(rest);
    } catch (e) {
      return String(Date.now());
    }
  };

  const markSettingsUpdated = () => {
    try {
      localStorage.setItem(SETTINGS_UPDATED_AT_KEY, new Date().toISOString());
    } catch (e) {}
  };
  const getLocalSettingsUpdatedAt = (): string => {
    try {
      return localStorage.getItem(SETTINGS_UPDATED_AT_KEY) || '';
    } catch (e) {
      return '';
    }
  };
  const getPendingDeletes = (): string[] => {
    try {
      const raw = JSON.parse(localStorage.getItem(PENDING_DELETES_KEY) || '[]');
      return Array.isArray(raw) ? raw.filter((id: any) => typeof id === 'string' && id.length > 0) : [];
    } catch (e) {
      return [];
    }
  };
  const addPendingDeletes = (ids: string[]) => {
    if (!ids || ids.length === 0) return;
    try {
      const merged = Array.from(new Set([...getPendingDeletes(), ...ids.filter(Boolean)]));
      localStorage.setItem(PENDING_DELETES_KEY, JSON.stringify(merged));
    } catch (e) {}
  };
  const clearPendingDeletes = (consumedIds: string[]) => {
    if (!consumedIds || consumedIds.length === 0) return;
    try {
      const remaining = getPendingDeletes().filter(id => !consumedIds.includes(id));
      if (remaining.length === 0) {
        localStorage.removeItem(PENDING_DELETES_KEY);
      } else {
        localStorage.setItem(PENDING_DELETES_KEY, JSON.stringify(remaining));
      }
    } catch (e) {}
  };
  const getPendingTrashDeletes = (): string[] => {
    try {
      const raw = JSON.parse(localStorage.getItem(PENDING_TRASH_DELETES_KEY) || '[]');
      return Array.isArray(raw) ? raw.filter((id: any) => typeof id === 'string' && id.length > 0) : [];
    } catch (e) {
      return [];
    }
  };
  const addPendingTrashDeletes = (ids: string[]) => {
    if (!ids || ids.length === 0) return;
    try {
      const merged = Array.from(new Set([...getPendingTrashDeletes(), ...ids.filter(Boolean)]));
      localStorage.setItem(PENDING_TRASH_DELETES_KEY, JSON.stringify(merged));
    } catch (e) {}
  };
  const removePendingTrashDeletes = (ids: string[]) => {
    if (!ids || ids.length === 0) return;
    try {
      const remaining = getPendingTrashDeletes().filter(id => !ids.includes(id));
      if (remaining.length === 0) {
        localStorage.removeItem(PENDING_TRASH_DELETES_KEY);
      } else {
        localStorage.setItem(PENDING_TRASH_DELETES_KEY, JSON.stringify(remaining));
      }
    } catch (e) {}
  };
  const sanitizeTrashItems = (items: any[]): TrashItem[] => {
    if (!Array.isArray(items)) return [];
    const seen = new Set<string>();
    const clean: TrashItem[] = [];
    for (const raw of items) {
      if (!raw || typeof raw !== 'object' || !raw.id) continue;
      const id = String(raw.id);
      if (seen.has(id)) continue;
      seen.add(id);
      const type: 'list' | 'note' | 'label' = raw.type === 'note' ? 'note' : (raw.type === 'label' ? 'label' : 'list');
      let safeData: any = {};
      try {
        safeData = JSON.parse(JSON.stringify(raw.data || {}));
      } catch (e) {
        safeData = {};
      }
      if (type === 'list' && safeData && Array.isArray(safeData.rows)) {
        safeData.rows = safeData.rows.slice(0, 300).map((r: any, idx: number) => {
          if (!r || typeof r !== 'object') return { id: `row-${idx}`, status: 'none', image: '', audio: '', pdf: '' };
          const rowCopy: Record<string, any> = {
            id: String(r.id || `row-${idx}`),
            status: String(r.status || 'none'),
            image: '',
            audio: '',
            pdf: ''
          };
          Object.keys(r).forEach(k => {
            if (k === 'image' || k === 'audio' || k === 'pdf') {
              const val = typeof r[k] === 'string' ? r[k] : '';
              if (val.startsWith('__srvmedia__:') || val.startsWith('__idb_media__:')) {
                rowCopy[k] = val.slice(0, 240);
              }
            } else if (r[k] !== undefined) {
              rowCopy[k] = r[k];
            }
          });
          return rowCopy;
        });
      }
      const resolvedRowCount = typeof raw.rowCount === 'number' && Number.isFinite(raw.rowCount)
        ? raw.rowCount
        : (Array.isArray(safeData?.rows) ? safeData.rows.length : undefined);
      clean.push({
        id,
        type,
        originalId: String(raw.originalId || id),
        title: String(raw.title || 'Pa titull').slice(0, 200),
        deletedAt: String(raw.deletedAt || new Date().toISOString()),
        data: safeData,
        ...(resolvedRowCount !== undefined ? { rowCount: resolvedRowCount } : {}),
        tags: Array.isArray(raw.tags) ? raw.tags.map((tg: any) => String(tg)) : []
      });
      if (clean.length >= 100) break;
    }
    return clean;
  };
  const mergeTrashItems = (base: TrashItem[], incoming: TrashItem[], pendingTrashDeletes: string[] = []): TrashItem[] => {
    const map = new Map<string, TrashItem>();
    sanitizeTrashItems(base).forEach(item => {
      if (!pendingTrashDeletes.includes(item.id)) map.set(item.id, item);
    });
    sanitizeTrashItems(incoming).forEach(item => {
      if (!pendingTrashDeletes.includes(item.id) && !map.has(item.id)) {
        map.set(item.id, item);
      }
    });
    return Array.from(map.values())
      .sort((a, b) => new Date(b.deletedAt || 0).getTime() - new Date(a.deletedAt || 0).getTime())
      .slice(0, 100);
  };
  const buildTrashFromDoc = (docObj: GridDocument): TrashItem => {
    const cleanHeaders = Array.isArray(docObj.headers) ? docObj.headers : ['Kolona 1', 'Kolona 2', 'Kolona 3'];
    const usedRowsCount = Array.isArray(docObj.rows)
      ? docObj.rows.filter(r => cleanHeaders.some((_, ci) => String(r?.[`col${ci + 1}`] || '').trim()) || (r?.status && r.status !== 'none') || r?.image || r?.audio || r?.pdf).length
      : 0;
    return {
      id: `trash-list-${docObj.id}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      type: 'list',
      originalId: docObj.id,
      title: docObj.title || 'Listë pa titull',
      deletedAt: new Date().toISOString(),
      data: sanitizeTrashItems([{
        id: 'tmp',
        type: 'list',
        originalId: docObj.id,
        title: docObj.title || 'Listë pa titull',
        deletedAt: new Date().toISOString(),
        data: docObj
      }])[0]?.data || docObj,
      rowCount: usedRowsCount || (Array.isArray(docObj.rows) ? docObj.rows.length : 0),
      tags: Array.isArray(docObj.tags) ? docObj.tags : []
    };
  };
  const buildTrashFromNote = (noteObj: any, fallbackTitle = 'Shënim Sekret'): TrashItem => {
    const titleVal = noteObj?.name || noteObj?.text || fallbackTitle;
    return {
      id: `trash-note-${noteObj?.id || 'note'}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      type: 'note',
      originalId: String(noteObj?.id || `note-${Date.now()}`),
      title: String(titleVal || fallbackTitle),
      deletedAt: new Date().toISOString(),
      data: noteObj && typeof noteObj === 'object' ? noteObj : { name: titleVal, content: String(noteObj || '') },
      tags: []
    };
  };
  const buildTrashFromLabel = (labelName: string, docIds: string[] = []): TrashItem => ({
    id: `trash-label-${encodeURIComponent(labelName)}-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    type: 'label',
    originalId: labelName,
    title: `#${labelName}`,
    deletedAt: new Date().toISOString(),
    data: { name: labelName, docIds },
    rowCount: docIds.length,
    tags: [labelName]
  });
  const appendItemsToTrashState = (newEntries: TrashItem[]): TrashItem[] => {
    if (!newEntries || newEntries.length === 0) return latestTrashItemsRef.current;
    removePendingTrashDeletes(newEntries.map(e => e.id));
    const nextTrash = sanitizeTrashItems([...newEntries, ...latestTrashItemsRef.current]);
    setTrashItems(nextTrash);
    latestTrashItemsRef.current = nextTrash;
    try {
      localStorage.setItem(TRASH_ITEMS_KEY, JSON.stringify(nextTrash));
    } catch (e) {}
    if (onlineViewRef.current === 'cloud' || onlineViewRef.current === 'gist') {
      setOnlineTrashItems(nextTrash);
    }
    markSettingsUpdated();
    return nextTrash;
  };
  const markPendingSync = (deletedIds?: string[]) => {
    syncChangeSeqRef.current += 1;
    try {
      localStorage.setItem(PENDING_SYNC_KEY, new Date().toISOString());
      if (deletedIds && deletedIds.length > 0) {
        addPendingDeletes(deletedIds);
      }
    } catch (e) {}
  };
  const hasPendingSync = (): boolean => {
    try {
      return Boolean(localStorage.getItem(PENDING_SYNC_KEY)) || getPendingDeletes().length > 0 || getPendingTrashDeletes().length > 0;
    } catch (e) {
      return false;
    }
  };
  const clearPendingSyncIfClean = (seqAtStart: number) => {
    if (syncChangeSeqRef.current === seqAtStart) {
      try {
        localStorage.removeItem(PENDING_SYNC_KEY);
      } catch (e) {}
    }
  };

  // Translations helper
  const t = (sq: string, en: string, el?: string) => {
    if (language === 'sq') return sq;
    if (language === 'en') return en;
    return el ?? EL_TRANSLATIONS[en] ?? EL_TRANSLATIONS[sq] ?? translateDynamicToGreek(sq, en);
  };
  const getColorDisplayName = (name: string) => {
    const key = (name || '').toLowerCase();
    if (key === 'default' || key === 'origjinal') return t('Origjinal', 'Default');
    if (key === 'red' || key === 'e kuqe') return t('E Kuqe', 'Red');
    if (key === 'orange' || key === 'portokalli') return t('Portokalli', 'Orange');
    if (key === 'yellow' || key === 'e verdhë' || key === 'e verdhe') return t('E Verdhë', 'Yellow');
    if (key === 'green' || key === 'jeshile') return t('Jeshile', 'Green');
    if (key === 'blue' || key === 'blu') return t('Blu', 'Blue');
    if (key === 'purple' || key === 'vjollcë' || key === 'vjollce') return t('Vjollcë', 'Purple');
    if (key === 'pink' || key === 'rozë' || key === 'roze') return t('Rozë', 'Pink');
    if (key === 'gray' || key === 'gri') return t('Gri', 'Gray');
    return name;
  };
  const saveCustomLabels = (labels: string[], overrideDocs?: GridDocument[], triggerImmediateSync = true, trashOverride?: TrashItem[]) => {
    setCustomLabels(labels);
    latestCustomLabelsRef.current = labels;
    localStorage.setItem('customLabels', JSON.stringify(labels));
    markSettingsUpdated();
    markPendingSync();

    const docsToSync = overrideDocs || (latestDocsRef.current.length > 0 ? latestDocsRef.current : documents);
    if (triggerImmediateSync && navigator.onLine) {
       syncWithGoogleCloud(
         docsToSync,
         true,
         latestBlueTextRef.current,
         latestSecretListRef.current,
         labels,
         getPendingDeletes(),
         latestNotesColorRef.current,
         trashOverride !== undefined ? trashOverride : latestTrashItemsRef.current
       );
    }
  };
  const isDocAllDeletedX = (doc: any) => {
    if (!doc || !doc.rows || doc.rows.length === 0) return false;
    const contentRows = doc.rows.filter((r: any) => 
      (r.col1 && r.col1.trim()) || 
      (r.col2 && r.col2.trim()) || 
      (r.col3 && r.col3.trim()) || 
      (r.col4 && r.col4.trim())
    );
    if (contentRows.length === 0) return false;
    return contentRows.every((r: any) => r.status === 'x');
  };
  // Calculator handlers
  const handleCalcPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest('button')) return;
    setCalcIsDragging(true);
    setCalcDragOffset({
      x: e.clientX - calcPos.x,
      y: e.clientY - calcPos.y
    });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };
  const handleCalcPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!calcIsDragging) return;
    setCalcPos({
      x: e.clientX - calcDragOffset.x,
      y: e.clientY - calcDragOffset.y
    });
  };
  const handleCalcPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    setCalcIsDragging(false);
    try {
      (e.target as HTMLElement).releasePointerCapture(e.pointerId);
    } catch (err) {}
  };
  const handleToggleCalcZoom = () => {
    const steps = [1, 1.25, 1.5, 0.85];
    const idx = steps.indexOf(calcZoom);
    const next = steps[(idx + 1) % steps.length];
    setCalcZoom(next);
    localStorage.setItem('grid_notepad_calc_zoom', String(next));
  };
  const handleCalcInput = (btn: string) => {
    const isErrorState = isCalcErrorToken(calcDisplay);
    const isBinaryOp = (ch: string) => ch === '+' || ch === '-' || ch === '×' || ch === 'x' || ch === '*' || ch === '÷' || ch === '/';

    if (btn === 'C') {
      setCalcDisplay('0');
      setCalcLastExpr('');
      return;
    }

    if (btn === 'Del' || btn === '←') {
      if (isErrorState) {
        setCalcDisplay('0');
        setCalcLastExpr('');
      } else if (calcDisplay.length > 1) {
        setCalcDisplay(calcDisplay.slice(0, -1));
      } else {
        setCalcDisplay('0');
      }
      return;
    }

    if (btn === '=') {
      if (isErrorState) return;
      const trimmedDisplay = calcDisplay.replace(/[+\-*/×x÷.]+$/, '') || '0';
      const res = evaluateCalcExpression(trimmedDisplay, { trimTrailingOperator: true });
      if (res.ok && res.value !== undefined) {
        setCalcLastExpr(`${trimmedDisplay} =`);
        setCalcDisplay(res.value);
      } else {
        setCalcLastExpr(`${calcDisplay} =`);
        setCalcDisplay(
          res.error === 'Ndalohet ÷ 0'
            ? t('Ndalohet ÷ 0', 'Division by 0 not allowed', 'Απαγορεύεται ÷ 0')
            : t('Gabim', 'Error', 'Σφάλμα')
        );
      }
      return;
    }

    if (isBinaryOp(btn)) {
      const normalizedOp = btn === 'x' || btn === '*' ? '×' : btn === '/' ? '÷' : btn;
      if (isErrorState) {
        setCalcLastExpr('');
        setCalcDisplay('0' + normalizedOp);
        return;
      }
      const lastChar = calcDisplay.slice(-1);
      if (lastChar === '.') {
        setCalcDisplay(calcDisplay.slice(0, -1) + normalizedOp);
      } else if (isBinaryOp(lastChar)) {
        // Replace trailing operator so accidental double-taps never break the chain
        setCalcDisplay(calcDisplay.slice(0, -1) + normalizedOp);
      } else {
        setCalcDisplay(calcDisplay + normalizedOp);
      }
      return;
    }

    if (btn === '%') {
      if (isErrorState) return;
      const lastChar = calcDisplay.slice(-1);
      if (lastChar === '%' || isBinaryOp(lastChar)) return;
      if (lastChar === '.') {
        setCalcDisplay(calcDisplay.slice(0, -1) + '%');
      } else {
        setCalcDisplay(calcDisplay + '%');
      }
      return;
    }

    if (btn === '.') {
      if (isErrorState || calcDisplay === '0') {
        setCalcLastExpr('');
        setCalcDisplay('0.');
        return;
      }
      const lastChar = calcDisplay.slice(-1);
      if (lastChar === '%') {
        setCalcDisplay(calcDisplay + '×0.');
        return;
      }
      if (isBinaryOp(lastChar)) {
        setCalcDisplay(calcDisplay + '0.');
        return;
      }
      // Prevent multiple decimal dots inside the current numeric token
      const parts = calcDisplay.split(/[+\-×x*÷/()]/);
      const currentToken = parts[parts.length - 1] || '';
      if (currentToken.includes('.')) return;
      setCalcDisplay(calcDisplay + '.');
      return;
    }

    // Numeric digit 0-9
    if (calcDisplay === '0' || isErrorState) {
      setCalcLastExpr('');
      setCalcDisplay(btn);
    } else if (calcDisplay.slice(-1) === '%') {
      setCalcDisplay(calcDisplay + '×' + btn);
    } else {
      setCalcDisplay(calcDisplay + btn);
    }
  };
const handleRenameCustomLabel = (index: number) => {
  const oldName = customLabels[index];
  setLabelModal({
    isOpen: true,
    mode: 'rename',
    index,
    value: oldName
  });
};
const handleSaveLabelModal = () => {
  const trimmed = labelModal.value.trim();
  if (!trimmed) {
    showToast(t("Emri i etiketës nuk mund të jetë i zbrazët!", "Label name cannot be empty!"));
    return;
  }
  if (labelModal.mode === 'add') {
    if (customLabels.includes(trimmed)) {
      showToast(t("Kjo etiketë ekziston tashmë!", "This label already exists!"));
      return;
    }
    const updated = [...customLabels, trimmed];
    saveCustomLabels(updated, latestDocsRef.current, true);
    showToast(t("Etiketa u shtua dhe u sinkronizua me Cloud!", "Label added and synced to Cloud!"));
  } else {
    const index = labelModal.index!;
    const oldName = customLabels[index];
    if (trimmed === oldName) {
      setLabelModal(prev => ({ ...prev, isOpen: false }));
      return;
    }
    if (customLabels.includes(trimmed)) {
      showToast(t("Kjo etiketë ekziston tashmë!", "This label already exists!"));
      return;
    }
    const updatedLabels = [...customLabels];
    updatedLabels[index] = trimmed;
    const nowIso = new Date().toISOString();
    // Update all documents that had the old tag to have the new tag with fresh updatedAt
    const updatedDocs = documents.map(doc => {
       if (doc.tags && doc.tags.includes(oldName)) {
          return {
             ...doc,
             tags: doc.tags.map(tagItem => tagItem === oldName ? trimmed : tagItem),
             updatedAt: nowIso
          };
       }
       return doc;
    });
    setDocuments(updatedDocs);
    latestDocsRef.current = updatedDocs;
    saveDocsLocalSafe(updatedDocs);
    saveCustomLabels(updatedLabels, updatedDocs, true);
    
    if (selectedLabelFolder === oldName) {
       setSelectedLabelFolder(trimmed);
    }
    showToast(t("Etiketa u ndryshua dhe u sinkronizua!", "Label renamed and synced!"));
  }
  setLabelModal({ isOpen: false, mode: 'add', value: '' });
};
  const handleMoveDocument = (doc: any, targetLabel: string, destName: string) => {
     executeProtectedAction(() => {
        setTransferDocId(null);
        setTransferringInfo({ docTitle: doc.title, destName });
        
        setTimeout(() => {
           const nowIso = new Date().toISOString();
           const baseDocs = latestDocsRef.current.length > 0 ? latestDocsRef.current : documents;
           const updatedDocs = baseDocs.map(d => {
              if (d.id === doc.id) {
                 const otherTags = (d.tags || []).filter(tag => !latestCustomLabelsRef.current.includes(tag));
                 const newTags = targetLabel === 'default' 
                    ? otherTags 
                    : [...otherTags, targetLabel];
                 return { ...d, tags: newTags, updatedAt: nowIso };
              }
              return d;
           });
           
           setDocuments(updatedDocs);
           latestDocsRef.current = updatedDocs;
           saveDocsLocalSafe(updatedDocs);
           triggerAutoSave(updatedDocs, true);
           setTransferringInfo(null);
           showToast(
              t(
                 `Lista "${doc.title}" u transferua dhe u sinkronizua te: ${destName}`, 
                 `List "${doc.title}" moved & synced to: ${destName}`
              )
           );
        }, 600);
     });
  };
  const handleDeleteCustomLabel = (index: number) => {
     const labelName = customLabels[index];
     setLabelToDelete({ index, name: labelName });
  };
  const executeDeleteCustomLabel = (index: number) => {
     const labelName = customLabels[index];
     const affectedDocIds = documents.filter(d => d.tags && d.tags.includes(labelName)).map(d => d.id);
     const trashEntry = buildTrashFromLabel(labelName, affectedDocIds);
     const nextTrash = appendItemsToTrashState([trashEntry]);
     const updatedLabels = customLabels.filter((_, i) => i !== index);
     const nowIso = new Date().toISOString();
     // Remove tag from documents with fresh updatedAt
     const updatedDocs = documents.map(doc => {
        if (doc.tags && doc.tags.includes(labelName)) {
           return {
              ...doc,
              tags: doc.tags.filter(tagItem => tagItem !== labelName),
              updatedAt: nowIso
           };
        }
        return doc;
     });
     setDocuments(updatedDocs);
     latestDocsRef.current = updatedDocs;
     saveDocsLocalSafe(updatedDocs);
     saveCustomLabels(updatedLabels, updatedDocs, true, nextTrash);
     if (selectedLabelFolder === labelName) {
        setSelectedLabelFolder(null);
     }
     showToast(t("Etiketa u fshi dhe u ruajt te Listat në Kosh (Cloud, Firebase & Gist)!", "Label deleted and archived to Trash online!"));
     setLabelToDelete(null);
  };
  const [blueModal, setBlueModal] = useState(false);
  const [blueText, setBlueText] = useState('');
  const [secretList, setSecretList] = useState<{id: string, text: string, done: boolean, name?: string, content?: string, color?: string, createdAt?: string, updatedAt?: string}[]>([]);
  latestBlueTextRef.current = blueText;
  latestSecretListRef.current = secretList;
  const [secretActiveTab, setSecretActiveTab] = useState<'editor' | 'list'>('editor');
  const secretFileInputRef = useRef<HTMLInputElement | null>(null);
  const [cloudDocs, setCloudDocs] = useState<GridDocument[]>([]);
  cloudDocsRef.current = cloudDocs;
  const [isFetchingCloud, setIsFetchingCloud] = useState(false);
  const [selectedCloudDocIds, setSelectedCloudDocIds] = useState<string[]>([]);
  const [previewModalDoc, setPreviewModalDoc] = useState<GridDocument | null>(null);
  const [fullViewDoc, setFullViewDoc] = useState<GridDocument | null>(null);
  const fileInputBackupRef = useRef<HTMLInputElement | null>(null);
  const handleUnifiedCloudSync = async () => {
     if (!user) {
        showToast(t("Ju lutem kyçuni me Email/Password ose Google për të sinkronizuar të dhënat.", "Please sign in with Email/Password or Google to sync your data."));
        setAuthModal(true);
        return;
     }
     const mail = getActiveUid()!;
     const fsUid = getFirestoreUid();
     const pendingDeletes = getPendingDeletes();
     const localIsDirty = hasPendingSync();
     
     showToast(t("⚡ Duke u lidhur me Google Cloud & Firebase...", "⚡ Connecting to Google Cloud & Firebase..."));
     // 1. Fetch current cloud database state (/api/cloud/load) AND Firestore
     const idToken = auth.currentUser ? await auth.currentUser.getIdToken(true).catch(() => null) : null;
     const endpoints = getApiEndpoints(`/api/cloud/load?userId=${encodeURIComponent(mail)}`);
     let cloudData: any = null;
     for (const ep of endpoints) {
        try {
           const headers: Record<string, string> = {};
           if (idToken) {
              headers['Authorization'] = `Bearer ${idToken}`;
           }
           const finalEp = idToken ? `${ep}&idToken=${encodeURIComponent(idToken)}` : ep;
           const res = await fetch(finalEp, { headers });
           if (res.ok && res.headers.get('content-type')?.includes('application/json')) {
              const json = await res.json();
              if (json && json.success) {
                 cloudData = json;
                 break;
              }
           }
        } catch (e) {
           console.warn("Error fetching cloud during smart sync:", e);
        }
     }
     const fsRemote = await fetchFirestoreSnapshot();

     let mergedDocs = [...(latestDocsRef.current.length > 0 ? latestDocsRef.current : documents)];
     if (cloudData && Array.isArray(cloudData.documents)) {
        const hydratedCloudDocs = await hydrateServerMediaRefs(cloudData.documents, idToken);
        const filteredCloud = hydratedCloudDocs.filter((d: any) => d && !pendingDeletes.includes(d.id));
        mergedDocs = mergeDocsByUpdatedAt(mergedDocs, filteredCloud);
     }
     if (fsRemote.docs.length > 0) {
        const filteredFs = fsRemote.docs.filter((d: any) => d && !pendingDeletes.includes(d.id));
        mergedDocs = mergeDocsByUpdatedAt(mergedDocs, filteredFs);
     }
     if (pendingDeletes.length > 0) {
        mergedDocs = mergedDocs.filter(d => !pendingDeletes.includes(d.id));
     }

     let mergedBlueText = latestBlueTextRef.current;
     let mergedSecretList = [...latestSecretListRef.current];
     let mergedLabels = [...latestCustomLabelsRef.current];
     let mergedTrashItems = [...latestTrashItemsRef.current];
     let mergedPadNotes = [...latestPadNotesRef.current];
     const pendingTrashDeletes = getPendingTrashDeletes();
     let mergedNotesColor = latestNotesColorRef.current;
     let mergedTextColorMode = latestTextColorModeRef.current;
     let mergedTextSize = latestTextSizeRef.current;
     let mergedTextWeight = latestTextWeightRef.current;
     const localSettingsTime = getLocalSettingsUpdatedAt() ? new Date(getLocalSettingsUpdatedAt()).getTime() : 0;

     const applyRemoteSettings = (remote: any) => {
        if (!remote) return;
        const remoteSettingsTime = remote.settingsUpdatedAt ? new Date(remote.settingsUpdatedAt).getTime() : (remote.lastUpdated ? new Date(remote.lastUpdated).getTime() : 0);
        const remoteIsNewer = !localIsDirty && remoteSettingsTime > localSettingsTime;

        const remoteBlue = remote.blueText || '';
        if (!mergedBlueText && remoteBlue) {
           mergedBlueText = remoteBlue;
        } else if (mergedBlueText && remoteBlue && mergedBlueText !== remoteBlue && !localIsDirty) {
           if (remoteIsNewer && remoteBlue.length >= mergedBlueText.length) {
              mergedBlueText = remoteBlue;
           } else if (!mergedBlueText.includes(remoteBlue) && !remoteBlue.includes(mergedBlueText)) {
              mergedBlueText = remoteBlue + "\n\n--- Sinkronizuar nga Pajisja tjetër ---\n" + mergedBlueText;
           } else if (remoteBlue.length > mergedBlueText.length) {
              mergedBlueText = remoteBlue;
           }
        }
        const remoteSecrets: any[] = Array.isArray(remote.secretList) ? remote.secretList : [];
        const localSecretMap = new Map<string, any>();
        mergedSecretList.forEach(item => localSecretMap.set(item.id, item));
        remoteSecrets.forEach(cItem => {
           if (!localSecretMap.has(cItem.id)) {
              const hasContent = cItem.content !== undefined;
              const normalized = {
                 id: cItem.id,
                 name: cItem.name || cItem.text || t('Pa Emër', 'Unnamed'),
                 content: hasContent ? cItem.content : (cItem.note || ''),
                 text: cItem.name || cItem.text || t('Pa Emër', 'Unnamed'),
                 color: cItem.color || 'default',
                 done: !!cItem.done,
                 createdAt: cItem.createdAt || new Date().toISOString(),
                 updatedAt: cItem.updatedAt || new Date().toISOString()
              };
              if (!localIsDirty || remoteIsNewer) {
                 mergedSecretList.push(normalized);
                 localSecretMap.set(cItem.id, normalized);
              }
           } else {
              const localItem = localSecretMap.get(cItem.id);
              if (localItem) {
                 localItem.done = localItem.done || cItem.done;
                 const cloudUpdate = cItem.updatedAt ? new Date(cItem.updatedAt).getTime() : 0;
                 const localUpdate = localItem.updatedAt ? new Date(localItem.updatedAt).getTime() : 0;
                 if (cloudUpdate > localUpdate || (!localItem.content && cItem.content)) {
                    localItem.name = cItem.name || cItem.text || localItem.name;
                    localItem.content = cItem.content !== undefined ? cItem.content : (cItem.note || localItem.content);
                    localItem.text = localItem.name;
                    if (cItem.color) localItem.color = cItem.color;
                    if (cItem.updatedAt) {
                       localItem.updatedAt = cItem.updatedAt;
                    }
                 } else if (!localItem.color && cItem.color) {
                    localItem.color = cItem.color;
                 }
              }
           }
        });
        if (Array.isArray(remote.customLabels)) {
           remote.customLabels.forEach((lbl: string) => {
              if (lbl && !mergedLabels.includes(lbl)) {
                 if (!localIsDirty || remoteIsNewer) {
                    mergedLabels.push(lbl);
                 }
              }
           });
        }
        if (Array.isArray(remote.trashItems)) {
           if (remoteIsNewer && pendingTrashDeletes.length === 0) {
              mergedTrashItems = sanitizeTrashItems(remote.trashItems);
           } else {
              mergedTrashItems = mergeTrashItems(mergedTrashItems, remote.trashItems, pendingTrashDeletes);
           }
        }
        if (Array.isArray(remote.padNotes)) {
           mergedPadNotes = mergePadNotesList(mergedPadNotes, remote.padNotes);
        }
        if (remote.notesColor && ((remoteIsNewer && !localIsDirty) || (remote.notesColor !== 'default' && mergedNotesColor === 'default'))) {
           mergedNotesColor = remote.notesColor;
        }
        if (remote.textColorMode && ((remoteIsNewer && !localIsDirty) || (remote.textColorMode !== 'default' && mergedTextColorMode === 'default'))) {
           mergedTextColorMode = remote.textColorMode;
        }
        if (typeof remote.textSize === 'number' && remoteIsNewer) {
           mergedTextSize = remote.textSize;
        }
        if (typeof remote.textWeight === 'number' && remoteIsNewer) {
           mergedTextWeight = remote.textWeight;
        }
        if (remote.gistToken && !gistToken) {
           setGistToken(remote.gistToken);
           localStorage.setItem('grid_notepad_gist_token', remote.gistToken);
        }
        if (remote.gistId && !gistId) {
           setGistId(remote.gistId);
           localStorage.setItem('grid_notepad_gist_id', remote.gistId);
        }
        if (remote.pin && !localStorage.getItem('grid_notepad_pin')) {
           localStorage.setItem('grid_notepad_pin', remote.pin);
        }
        if (remote.geminiKey && !userGeminiKey) {
           setUserGeminiKey(remote.geminiKey);
           localStorage.setItem('grid_notepad_gemini_key', remote.geminiKey);
        }
     };

     applyRemoteSettings(cloudData);
     applyRemoteSettings(fsRemote.settings);
     mergedTrashItems = sanitizeTrashItems(mergedTrashItems.filter(it => !pendingTrashDeletes.includes(it.id)));

     // 2. Set the merged state locally and save to localStorage
     setDocuments(mergedDocs);
     latestDocsRef.current = mergedDocs;
     setCloudDocs(mergedDocs);
     saveDocsLocalSafe(mergedDocs);
     setBlueText(mergedBlueText);
     latestBlueTextRef.current = mergedBlueText;
     localStorage.setItem('grid_notepad_blue', mergedBlueText);
     setSecretList(mergedSecretList);
     latestSecretListRef.current = mergedSecretList;
     localStorage.setItem('grid_notepad_secret_list', JSON.stringify(mergedSecretList));
     setCustomLabels(mergedLabels);
     latestCustomLabelsRef.current = mergedLabels;
     localStorage.setItem('customLabels', JSON.stringify(mergedLabels));
     setTrashItems(mergedTrashItems);
     latestTrashItemsRef.current = mergedTrashItems;
     setOnlineTrashItems(mergedTrashItems);
     localStorage.setItem(TRASH_ITEMS_KEY, JSON.stringify(mergedTrashItems));
     setPadNotes(mergedPadNotes);
     latestPadNotesRef.current = mergedPadNotes;
     try {
       localStorage.setItem('grid_notepad_pads_v1', JSON.stringify(mergedPadNotes));
     } catch {}
     setNotesColor(mergedNotesColor);
     latestNotesColorRef.current = mergedNotesColor;
     localStorage.setItem('grid_notepad_notes_color', mergedNotesColor);
     if (mergedTextColorMode !== textColorMode) {
        setTextColorMode(mergedTextColorMode);
        latestTextColorModeRef.current = mergedTextColorMode;
        localStorage.setItem('grid_notepad_text_color_mode', mergedTextColorMode);
     }
     if (mergedTextSize !== textSize) {
        setTextSize(mergedTextSize);
        latestTextSizeRef.current = mergedTextSize;
        localStorage.setItem('grid_notepad_text_size', String(mergedTextSize));
     }
     if (mergedTextWeight !== textWeight) {
        setTextWeight(mergedTextWeight);
        latestTextWeightRef.current = mergedTextWeight;
        localStorage.setItem('grid_notepad_text_weight', String(mergedTextWeight));
     }
     // 3. Upload the merged/fully synchronized state back to Cloud, Firebase & Gist
     const synced = await syncWithGoogleCloud(mergedDocs, true, mergedBlueText, mergedSecretList, mergedLabels, pendingDeletes, mergedNotesColor, mergedTrashItems);
     
     if (synced || fsUid) {
        showToast(t("⚡ Sinkronizimi i zgjuar me Cloud, Firebase & Gist u krye me sukses 100%!", "⚡ Smart sync with Cloud, Firebase & Gist 100% complete!"));
     } else {
        showToast(t("Të dhënat u sinkronizuan lokalisht në këtë pajisje.", "Data synced locally on this device."));
     }
  };
  const handleSelectAllCloudDocs = () => {
     if (selectedCloudDocIds.length === documents.length && documents.length > 0) {
        setSelectedCloudDocIds([]);
     } else {
        setSelectedCloudDocIds(documents.map(d => d.id));
     }
  };
  const handleDeleteSelectedCloudDocs = (docIdToDelete?: string) => {
     const idsToDelete = docIdToDelete ? [docIdToDelete] : selectedCloudDocIds;
     if (idsToDelete.length === 0) {
        showToast(t("Zgjidhni të paktën një dokument për ta fshirë.", "Select at least one document to delete."));
        return;
     }
     setCloudDocsToDeleteBatch(idsToDelete);
  };

  const executeDeleteSelectedCloudDocs = async () => {
     if (!cloudDocsToDeleteBatch || cloudDocsToDeleteBatch.length === 0) return;
     const idsToDelete = cloudDocsToDeleteBatch;
     const deletedDocs = documents.filter(d => idsToDelete.includes(d.id));
     const nextTrash = appendItemsToTrashState(deletedDocs.map(buildTrashFromDoc));
     const newDocs = documents.filter(d => !idsToDelete.includes(d.id));
     setDocuments(newDocs);
     latestDocsRef.current = newDocs;
     setSelectedCloudDocIds([]);
     saveDocsLocalSafe(newDocs);
     markPendingSync(idsToDelete);
     if (activeDocId && idsToDelete.includes(activeDocId)) {
        if (newDocs.length > 0) openDocument(newDocs[0]);
        else createNewDocument();
     }
     showToast(t("Dokumentet u fshinë dhe u ruajtën te Listat në Kosh online!", "Documents deleted and saved to online Trash!"));
     await syncWithGoogleCloud(newDocs, false, undefined, undefined, undefined, idsToDelete, undefined, nextTrash);
     setCloudDocsToDeleteBatch(null);
  };
  const handleExportBackup = (docToExport?: GridDocument) => {
     const exportData = docToExport ? [docToExport] : (selectedCloudDocIds.length > 0 ? documents.filter(d => selectedCloudDocIds.includes(d.id)) : documents);
     const content = JSON.stringify(exportData, null, 2);
     const blob = new Blob([content], { type: 'application/json;charset=utf-8' });
     const filename = `notebook_cloud_backup_${new Date().toISOString().slice(0, 10)}.json`;
     handleDownload(blob, filename, 'application/json', t('Backup Cloud', 'Cloud Backup'));
  };
  const handleImportBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
     const file = e.target.files?.[0];
     if (!file) return;
     const reader = new FileReader();
     reader.onload = async (event) => {
        try {
           const content = event.target?.result as string;
           const parsed = JSON.parse(content);
           if (Array.isArray(parsed) && parsed.length > 0) {
              const mergedMap = new Map<string, GridDocument>();
              documents.forEach(d => mergedMap.set(d.id, d));
              parsed.forEach((d: any) => {
                 if (d && d.id) mergedMap.set(d.id, d);
              });
              const updated = Array.from(mergedMap.values());
              setDocuments(updated);
              saveDocsLocalSafe(updated);
              showToast(t(`U importuan me sukses ${parsed.length} dokumente! Po sinkronizohen në Cloud...`, `Imported ${parsed.length} documents successfully! Syncing to Cloud...`));
              await syncWithGoogleCloud(updated, false);
           } else {
              showToast(t("Skedar backup i pavlefshëm.", "Invalid backup file."));
           }
        } catch (err) {
           showToast(t("Gabim gjatë leximit të skedarit backup.", "Error reading backup file."));
        }
     };
     reader.readAsText(file);
  };
  const [aiChatModal, setAiChatModal] = useState(false);
  const [aiChatInput, setAiChatInput] = useState(() => localStorage.getItem('grid_aichat_input') || '');
  const [aiChatResponse, setAiChatResponse] = useState('');
  const [debugLogsModal, setDebugLogsModal] = useState(false);
  const [debugLogs, setDebugLogs] = useState<string[]>([]);
  
  const appendDebugLog = (msg: string) => {
     const timestamp = new Date().toLocaleTimeString();
     const logEntry = `[${timestamp}] ${msg}`;
     console.log(logEntry);
     setDebugLogs(prev => {
        const updated = [...prev, logEntry].slice(-300);
        try {
           localStorage.setItem('grid_notepad_debug_logs', JSON.stringify(updated));
           window.dispatchEvent(new Event('debug-log-updated'));
        } catch(e) {}
        return updated;
     });
  };
  const getActiveUid = () => {
     const customUid = localStorage.getItem('grid_notepad_custom_uid');
     if (customUid) return customUid;
     if (user) {
        return (user.email || user.uid).toLowerCase();
     }
     if (auth.currentUser) {
        return (auth.currentUser.email || auth.currentUser.uid).toLowerCase();
     }
     return null;
  };
  const getFirestoreUid = () => {
     if (auth.currentUser) {
        return auth.currentUser.email || auth.currentUser.uid;
     }
     if (user) {
        return user.email || user.uid;
     }
     return getActiveUid();
  };
  const stripUndefinedDeep = (val: any): any => {
     if (val === undefined) return undefined;
     if (val === null || typeof val !== 'object') return val;
     if (Array.isArray(val)) {
        return val.map((item) => stripUndefinedDeep(item)).filter((item) => item !== undefined);
     }
     const out: Record<string, any> = {};
     for (const k of Object.keys(val)) {
        const cleaned = stripUndefinedDeep(val[k]);
        if (cleaned !== undefined) {
           out[k] = cleaned;
        }
     }
     return out;
  };
  const sanitizeDocForFirestore = (docObj: GridDocument, fsUid: string) => {
     const safeId = (docObj.id || `doc-${Date.now()}`).replace(/[^a-zA-Z0-9_\-\.:@]/g, '_').slice(0, 128);
     const cleanRows = (Array.isArray(docObj.rows) ? docObj.rows : []).slice(0, 5000).map((r, idx) => {
        const cleanRow: Record<string, any> = {
           id: String(r?.id || `row-${idx}`),
           status: String(r?.status || 'none'),
           image: typeof r?.image === 'string' ? r.image : '',
           audio: typeof r?.audio === 'string' ? r.audio : '',
           pdf: typeof r?.pdf === 'string' ? r.pdf : '',
        };
        if (typeof r?.imageName === 'string' && r.imageName) cleanRow.imageName = String(r.imageName).slice(0, 160);
        if (typeof r?.audioName === 'string' && r.audioName) cleanRow.audioName = String(r.audioName).slice(0, 160);
        if (typeof r?.audioMime === 'string' && r.audioMime) cleanRow.audioMime = String(r.audioMime).slice(0, 80);
        if (typeof r?.pdfName === 'string' && r.pdfName) cleanRow.pdfName = String(r.pdfName).slice(0, 160);
        if (typeof r?.pdfSize === 'number' && Number.isFinite(r.pdfSize)) cleanRow.pdfSize = r.pdfSize;
        if (r?.textColor) cleanRow.textColor = String(r.textColor);
        if (r?.color) cleanRow.color = String(r.color);
        if (r && typeof r === 'object') {
           Object.keys(r).forEach(k => {
              if (r[k] !== undefined && cleanRow[k] === undefined) {
                 cleanRow[k] = r[k];
              }
           });
        }
        return cleanRow;
     });
     return stripUndefinedDeep({
        id: safeId,
        title: String(docObj.title || 'Pa titull').slice(0, 200),
        headers: (Array.isArray(docObj.headers) ? docObj.headers : []).slice(0, 50).map(h => String(h ?? '')),
        columnWidths: Array.isArray(docObj.columnWidths) ? docObj.columnWidths : [],
        tags: Array.isArray(docObj.tags) ? docObj.tags.map(tg => String(tg)) : [],
        textColor: docObj.textColor ? String(docObj.textColor) : 'default',
        pinned: Boolean(docObj.pinned),
        isReadOnly: Boolean(docObj.isReadOnly),
        autoGrowRows: Boolean(docObj.autoGrowRows),
        rows: cleanRows,
        createdAt: docObj.createdAt || new Date().toISOString(),
        updatedAt: docObj.updatedAt || new Date().toISOString(),
        userId: fsUid
     });
  };
  const buildFirestoreSettingsPayload = (
     fsUid: string,
     blueTextVal: string,
     secretListVal: any[],
     customLabelsVal: string[],
     notesColorVal: string,
     textColorModeVal: string,
     trashItemsVal: TrashItem[] = latestTrashItemsRef.current
  ) => {
     let safeSecrets: any[] = [];
     try {
        safeSecrets = JSON.parse(JSON.stringify(Array.isArray(secretListVal) ? secretListVal : []));
     } catch (e) {
        safeSecrets = [];
     }
     if (safeSecrets.length > 1000) safeSecrets = safeSecrets.slice(0, 1000);
     let safeTrash = sanitizeTrashItems(trashItemsVal);
     const rawPin = localStorage.getItem('grid_notepad_pin') || null;
     const rawGistToken = gistToken || localStorage.getItem('grid_notepad_gist_token') || null;
     const rawGistId = gistId || localStorage.getItem('grid_notepad_gist_id') || null;
     const rawGeminiKey = userGeminiKey || localStorage.getItem('grid_notepad_gemini_key') || null;
     let safePads: any[] = [];
     try {
        safePads = (Array.isArray(latestPadNotesRef.current) ? latestPadNotesRef.current : []).slice(0, 500).map((p: any) => ({
           id: String(p?.id || ''),
           title: String(p?.title || 'Pad pa titull').slice(0, 200),
           content: typeof p?.content === 'string' ? p.content.slice(0, 80000) : '',
           color: String(p?.color || 'default').slice(0, 40),
           pinned: Boolean(p?.pinned),
           createdAt: String(p?.createdAt || new Date().toISOString()),
           updatedAt: String(p?.updatedAt || new Date().toISOString()),
        }));
     } catch (e) {
        safePads = [];
     }
     const buildPayload = (trashList: TrashItem[], secretsList: any[], padsList: any[]) => stripUndefinedDeep({
        userId: String(fsUid || '').slice(0, 128),
        blueText: typeof blueTextVal === 'string' ? blueTextVal.slice(0, 100000) : '',
        secretList: secretsList,
        customLabels: Array.isArray(customLabelsVal) ? customLabelsVal.filter((v) => v != null).map((v) => String(v).slice(0, 200)).slice(0, 500) : [],
        trashItems: trashList,
        padNotes: padsList,
        notesColor: notesColorVal || 'default',
        textColorMode: textColorModeVal || 'default',
        textSize: Number.isFinite(latestTextSizeRef.current) ? latestTextSizeRef.current : (Number.isFinite(textSize) ? textSize : 12),
        textWeight: Number.isFinite(latestTextWeightRef.current) ? latestTextWeightRef.current : (Number.isFinite(textWeight) ? textWeight : 400),
        pin: rawPin ? String(rawPin).slice(0, 100) : null,
        gistToken: rawGistToken ? String(rawGistToken).slice(0, 200) : null,
        gistId: rawGistId ? String(rawGistId).slice(0, 200) : null,
        geminiKey: rawGeminiKey ? String(rawGeminiKey).slice(0, 200) : null,
        settingsUpdatedAt: getLocalSettingsUpdatedAt() || new Date().toISOString()
     });
     let payload = buildPayload(safeTrash, safeSecrets, safePads);
     if (JSON.stringify(payload).length > 750000) {
        safeTrash = safeTrash.slice(0, 50).map((it) => ({
           ...it,
           data: it.type === 'list' && it.data ? { ...it.data, rows: [] } : it.data
        }));
        payload = buildPayload(safeTrash, safeSecrets, safePads);
     }
     if (JSON.stringify(payload).length > 750000) {
        safeTrash = safeTrash.slice(0, 15);
        safePads = safePads.slice(0, 200).map((p: any) => ({ ...p, content: String(p.content || '').slice(0, 3000) }));
        payload = buildPayload(safeTrash, safeSecrets.slice(0, 300), safePads);
     }
     return payload;
  };
  const mergeDocsByUpdatedAt = (baseDocs: GridDocument[], incomingDocs: GridDocument[]): GridDocument[] => {
     const map = new Map<string, GridDocument>();
     baseDocs.forEach(d => {
        if (d && d.id) map.set(d.id, d);
     });
     const isUsableMedia = (v: any) => typeof v === 'string' && v.length > 0 && !v.startsWith('__fschunk__:');
     incomingDocs.forEach(cDoc => {
        if (!cDoc || !cDoc.id) return;
        const existing = map.get(cDoc.id);
        if (!existing) {
           map.set(cDoc.id, cDoc);
        } else {
           const existingTime = new Date(existing.updatedAt || existing.createdAt || 0).getTime();
           const incomingTime = new Date(cDoc.updatedAt || cDoc.createdAt || 0).getTime();
           if (incomingTime >= existingTime) {
              const mergedRows = Array.isArray(cDoc.rows) && Array.isArray(existing.rows)
                 ? cDoc.rows.map((r: any, idx: number) => {
                      if (!r) return r;
                      const prevRow = existing.rows.find((er: any) => er && r.id && er.id === r.id) || existing.rows[idx];
                      if (!prevRow) return r;
                      let nextRow = r;
                      if (!isUsableMedia(nextRow.image) && isUsableMedia(prevRow.image)) {
                         nextRow = { ...nextRow, image: prevRow.image, imageName: nextRow.imageName || prevRow.imageName };
                      }
                      if (!isUsableMedia(nextRow.audio) && isUsableMedia(prevRow.audio)) {
                         nextRow = { ...nextRow, audio: prevRow.audio, audioName: nextRow.audioName || prevRow.audioName, audioMime: nextRow.audioMime || prevRow.audioMime };
                      }
                      if (!isUsableMedia(nextRow.pdf) && isUsableMedia(prevRow.pdf)) {
                         nextRow = { ...nextRow, pdf: prevRow.pdf, pdfName: nextRow.pdfName || prevRow.pdfName, pdfSize: nextRow.pdfSize || prevRow.pdfSize };
                      }
                      return nextRow;
                   })
                 : cDoc.rows;
              map.set(cDoc.id, { ...cDoc, rows: mergedRows });
           }
        }
     });
     return Array.from(map.values());
  };
  const fetchFirestoreSnapshot = async (): Promise<{ docs: GridDocument[]; settings: any | null }> => {
     if (!auth.currentUser || !navigator.onLine) {
        return { docs: [], settings: null };
     }
     if (isFirestorePausedNow()) {
        return { docs: [], settings: null };
     }
     if (inFlightFirestoreSnapshotRef.current) {
        return inFlightFirestoreSnapshotRef.current;
     }
     if (lastFirestoreSnapshotCacheRef.current && Date.now() - lastFirestoreSnapshotCacheRef.current.ts < 3000) {
        return lastFirestoreSnapshotCacheRef.current.data;
     }
     const runPromise = (async () => {
     await resumeFirestoreNetwork();
     const candidateUids = Array.from(new Set([
        auth.currentUser.email,
        auth.currentUser.email ? auth.currentUser.email.toLowerCase() : null,
        auth.currentUser.uid,
        getActiveUid()
     ].filter((v): v is string => !!v)));

     const docsMap = new Map<string, GridDocument>();
     let settingsData: any | null = null;
     const syncedSigs = getSyncedFirestoreDocSigs();
     let sigsChanged = false;

     for (const candidateUid of candidateUids) {
        if (isFirestorePausedNow()) break;
        try {
           const q = query(collection(db, 'documents'), where('userId', '==', candidateUid));
           const snaps = await getDocs(q);
           snaps.forEach(docSnap => {
              const d = docSnap.data();
              if (d) {
                 const fullDoc = { id: docSnap.id, ...d } as GridDocument;
                 const existing = docsMap.get(fullDoc.id);
                 if (!existing || new Date(fullDoc.updatedAt || 0) > new Date(existing.updatedAt || 0)) {
                    docsMap.set(fullDoc.id, fullDoc);
                 }
              }
           });
        } catch (err) {
           if (isFirestoreQuotaError(err)) {
              tripFirestoreQuotaCooldown(false);
              break;
           }
           if (isFirestoreTransientNetworkError(err)) {
              tripFirestoreTransientCooldown('documents/list', err);
              break;
           }
           try {
              handleFirestoreError(err, OperationType.LIST, 'documents');
           } catch (handledErr) {
              console.warn('Firestore documents read fallback:', handledErr);
           }
        }
        if (!settingsData && !isFirestorePausedNow()) {
           try {
              const settingsSnap = await getDoc(doc(db, 'settings', candidateUid));
              if (settingsSnap.exists()) {
                 settingsData = settingsSnap.data();
                 try {
                    localStorage.setItem(FIRESTORE_SYNCED_SETTINGS_KEY, computeFirestoreSettingsSig(settingsData));
                 } catch (e) {}
              }
           } catch (err) {
              if (isFirestoreQuotaError(err)) {
                 tripFirestoreQuotaCooldown(false);
                 break;
              }
              if (isFirestoreTransientNetworkError(err)) {
                 tripFirestoreTransientCooldown(`settings/${candidateUid}`, err);
                 break;
              }
              try {
                 handleFirestoreError(err, OperationType.GET, `settings/${candidateUid}`);
              } catch (handledErr) {
                 console.warn('Firestore settings read fallback:', handledErr);
              }
           }
        }
     }
     const needsChunkReassembly = Array.from(docsMap.values()).some((d) =>
        Array.isArray(d.rows) &&
        d.rows.some((r) => (typeof r?.image === 'string' && r.image.startsWith('__fschunk__:')) || (typeof r?.audio === 'string' && r.audio.startsWith('__fschunk__:')) || (typeof r?.pdf === 'string' && r.pdf.startsWith('__fschunk__:')))
     );
     if (needsChunkReassembly && !isFirestorePausedNow()) {
        const chunkGroups = new Map<string, Array<{ chunkIndex: number; totalChunks: number; data: string }>>();
        for (const candidateUid of candidateUids) {
           if (isFirestorePausedNow()) break;
           try {
              const cq = query(collection(db, 'media_chunks'), where('userId', '==', candidateUid));
              const cSnaps = await getDocs(cq);
              cSnaps.forEach((cs) => {
                 const ch = cs.data() as any;
                 if (!ch || !ch.docId || !ch.rowId || !ch.kind || typeof ch.data !== 'string') return;
                 const gKey = `${ch.docId}::${ch.rowId}::${ch.kind}`;
                 const list = chunkGroups.get(gKey) || [];
                 list.push({ chunkIndex: Number(ch.chunkIndex) || 0, totalChunks: Number(ch.totalChunks) || 1, data: ch.data });
                 chunkGroups.set(gKey, list);
              });
           } catch (err) {
              if (isFirestoreQuotaError(err)) {
                 tripFirestoreQuotaCooldown(false);
                 break;
              }
              if (isFirestoreTransientNetworkError(err)) {
                 tripFirestoreTransientCooldown('media_chunks/list', err);
                 break;
              }
           }
        }
        docsMap.forEach((docItem) => {
           if (!Array.isArray(docItem.rows)) return;
           docItem.rows = docItem.rows.map((r) => {
              let nextRow = r;
              (['image', 'audio', 'pdf'] as const).forEach((kind) => {
                 const val = nextRow?.[kind];
                 if (typeof val === 'string' && val.startsWith('__fschunk__:')) {
                    const gKey = `${docItem.id}::${nextRow.id}::${kind}`;
                    const chunks = chunkGroups.get(gKey);
                    if (chunks && chunks.length > 0) {
                       const ordered = [...chunks].sort((a, b) => a.chunkIndex - b.chunkIndex);
                       nextRow = { ...nextRow, [kind]: ordered.map((c) => c.data).join('') };
                    } else {
                       nextRow = { ...nextRow, [kind]: '' };
                    }
                 }
              });
              return nextRow;
           });
        });
     }
     docsMap.forEach((fullDoc) => {
        syncedSigs[fullDoc.id] = computeFirestoreDocSig(fullDoc);
        sigsChanged = true;
     });
     if (sigsChanged) saveSyncedFirestoreDocSigs(syncedSigs);
     const result = { docs: Array.from(docsMap.values()), settings: settingsData };
     lastFirestoreSnapshotCacheRef.current = { ts: Date.now(), data: result };
     return result;
     })();
     inFlightFirestoreSnapshotRef.current = runPromise;
     try {
        return await runPromise;
     } finally {
        inFlightFirestoreSnapshotRef.current = null;
     }
  };
  const syncToFirestore = async (
     docsToSync: GridDocument[],
     deletedDocIds: string[] = [],
     blueTextVal: string = latestBlueTextRef.current,
     secretListVal: any[] = latestSecretListRef.current,
     customLabelsVal: string[] = latestCustomLabelsRef.current,
     notesColorVal: string = latestNotesColorRef.current,
     textColorModeVal: string = latestTextColorModeRef.current,
     trashItemsVal: TrashItem[] = latestTrashItemsRef.current,
     silent = true
  ): Promise<boolean> => {
     const runTask = async (): Promise<boolean> => {
     if (!auth.currentUser || !navigator.onLine) return false;
     if (isFirestorePausedNow()) {
        return false;
     }
     const fsUid = getFirestoreUid();
     if (!fsUid) return false;
     await resumeFirestoreNetwork();
     let ok = true;
     const syncedSigs = getSyncedFirestoreDocSigs();
     let sigsDirty = false;
     const runFirestoreWriteWithQuotaGuard = async <T,>(opPromise: Promise<T>): Promise<T> => {
        let unsubscribe: (() => void) | null = null;
        let timer: ReturnType<typeof setTimeout> | null = null;
        try {
           return await Promise.race([
              opPromise,
              new Promise<T>((_, reject) => {
                 unsubscribe = subscribeFirestoreQuotaTrip(() => {
                    reject(new Error('resource-exhausted: Firestore daily write quota exceeded'));
                 });
                 timer = setTimeout(() => {
                    reject(new Error('firestore-write-timeout'));
                 }, 20000);
              })
           ]);
        } finally {
           if (unsubscribe) unsubscribe();
           if (timer) clearTimeout(timer);
        }
     };

     for (const delId of deletedDocIds) {
        if (!delId || isFirestorePausedNow()) continue;
        const safeDelId = String(delId).replace(/[^a-zA-Z0-9_\-\.:@]/g, '_').slice(0, 128);
        try {
           const docRef = doc(db, 'documents', safeDelId);
           const existingSnap = await runFirestoreWriteWithQuotaGuard(getDoc(docRef));
           if (!existingSnap.exists()) {
              if (syncedSigs[safeDelId]) {
                 delete syncedSigs[safeDelId];
                 sigsDirty = true;
              }
              continue;
           }
           await runFirestoreWriteWithQuotaGuard(deleteDoc(docRef));
           if (syncedSigs[safeDelId]) {
              delete syncedSigs[safeDelId];
              sigsDirty = true;
           }
        } catch (err) {
           if (isFirestoreQuotaError(err)) {
              tripFirestoreQuotaCooldown(!silent);
              if (sigsDirty) saveSyncedFirestoreDocSigs(syncedSigs);
              return false;
           }
           ok = false;
           if (isFirestoreTransientNetworkError(err)) {
              tripFirestoreTransientCooldown(`documents/${safeDelId}`, err);
              if (sigsDirty) saveSyncedFirestoreDocSigs(syncedSigs);
              return false;
           }
           try {
              handleFirestoreError(err, OperationType.DELETE, `documents/${safeDelId}`);
           } catch (handled) {
              console.warn('Firestore delete doc notice:', handled);
           }
        }
     }

     for (const docObj of docsToSync) {
        if (!docObj || !docObj.id || isFirestorePausedNow()) continue;
        const sanitized = sanitizeDocForFirestore(docObj, fsUid);
        const nextSig = computeFirestoreDocSig(sanitized);
        if (syncedSigs[sanitized.id] === nextSig) {
           continue;
        }
        try {
           let docPayload = sanitized;
           const estimatedBytes = JSON.stringify(sanitized).length;
           if (estimatedBytes > 700000 && Array.isArray(sanitized.rows)) {
              const CHUNK_CHAR_LIMIT = 500000;
              const chunkOps: Array<{ chunkId: string; payload: any }> = [];
              const docSlug = sanitized.id.replace(/[^a-zA-Z0-9_\-\.:@]/g, '_').slice(0, 44);
              const offloadedRows = sanitized.rows.map((r: any, rIdx: number) => {
                 let updatedRow = r;
                 const safeRowId = String(r?.id || `row-${rIdx}`).replace(/[^a-zA-Z0-9_\-\.:@]/g, '_').slice(0, 44);
                 (['image', 'audio', 'pdf'] as const).forEach((kind) => {
                    const mediaVal = updatedRow?.[kind];
                    if (typeof mediaVal === 'string' && mediaVal.length > 50000 && !mediaVal.startsWith('__fschunk__:') && !mediaVal.startsWith('__srvmedia__:')) {
                       const totalChunks = Math.ceil(mediaVal.length / CHUNK_CHAR_LIMIT);
                       if (totalChunks <= 150) {
                          for (let ci = 0; ci < totalChunks; ci++) {
                             const sliceStr = mediaVal.slice(ci * CHUNK_CHAR_LIMIT, (ci + 1) * CHUNK_CHAR_LIMIT);
                             const chunkId = `${docSlug}_${safeRowId}_${kind === 'image' ? 'i' : kind === 'audio' ? 'a' : 'p'}_${ci}`.slice(0, 128);
                             chunkOps.push({
                                chunkId,
                                payload: {
                                   id: chunkId,
                                   docId: sanitized.id,
                                   userId: fsUid,
                                   rowId: String(r?.id || `row-${rIdx}`).slice(0, 128),
                                   kind,
                                   chunkIndex: ci,
                                   totalChunks,
                                   data: sliceStr,
                                   updatedAt: new Date().toISOString(),
                                },
                             });
                          }
                          updatedRow = {
                             ...updatedRow,
                             [kind]: `__fschunk__:${kind}:${String(r?.id || `row-${rIdx}`)}:${totalChunks}`,
                          };
                       }
                    }
                 });
                 return updatedRow;
              });
              for (let ci = 0; ci < chunkOps.length; ci += 3) {
                 const batchOps = chunkOps.slice(ci, ci + 3);
                 const execBatch = () => Promise.all(
                    batchOps.map((op) =>
                       runFirestoreWriteWithQuotaGuard(setDoc(doc(db, 'media_chunks', op.chunkId), op.payload, { merge: true }))
                    )
                 );
                 try {
                    await execBatch();
                 } catch (batchErr) {
                    if (isFirestoreQuotaError(batchErr) || isFirestoreTransientNetworkError(batchErr)) throw batchErr;
                    await execBatch();
                 }
              }
              docPayload = { ...sanitized, rows: offloadedRows };
           }
           await runFirestoreWriteWithQuotaGuard(setDoc(doc(db, 'documents', sanitized.id), docPayload, { merge: true }));
           syncedSigs[sanitized.id] = nextSig;
           sigsDirty = true;
        } catch (err) {
           if (isFirestoreQuotaError(err)) {
              tripFirestoreQuotaCooldown(!silent);
              if (sigsDirty) saveSyncedFirestoreDocSigs(syncedSigs);
              return false;
           }
           ok = false;
           if (isFirestoreTransientNetworkError(err)) {
              tripFirestoreTransientCooldown(`documents/${sanitized.id}`, err);
              if (sigsDirty) saveSyncedFirestoreDocSigs(syncedSigs);
              return false;
           }
           try {
              handleFirestoreError(err, OperationType.WRITE, `documents/${sanitized.id}`);
           } catch (handled) {
              console.warn('Firestore write doc notice:', handled);
           }
        }
     }
     if (sigsDirty) saveSyncedFirestoreDocSigs(syncedSigs);

     const settingsPayload = buildFirestoreSettingsPayload(
        fsUid,
        blueTextVal,
        secretListVal,
        customLabelsVal,
        notesColorVal,
        textColorModeVal,
        trashItemsVal
     );
     const nextSettingsSig = computeFirestoreSettingsSig(settingsPayload);
     let prevSettingsSig = '';
     try {
        prevSettingsSig = localStorage.getItem(FIRESTORE_SYNCED_SETTINGS_KEY) || '';
     } catch (e) {}
     if (nextSettingsSig !== prevSettingsSig && !isFirestorePausedNow()) {
        try {
           await runFirestoreWriteWithQuotaGuard(setDoc(doc(db, 'settings', fsUid), settingsPayload, { merge: true }));
           try {
              localStorage.setItem(FIRESTORE_SYNCED_SETTINGS_KEY, nextSettingsSig);
           } catch (e) {}
        } catch (err) {
           if (isFirestoreQuotaError(err)) {
              tripFirestoreQuotaCooldown(!silent);
              return false;
           }
           ok = false;
           if (isFirestoreTransientNetworkError(err)) {
              tripFirestoreTransientCooldown(`settings/${fsUid}`, err);
              return false;
           }
           try {
              handleFirestoreError(err, OperationType.WRITE, `settings/${fsUid}`);
           } catch (handled) {
              console.warn('Firestore write settings notice:', handled);
           }
        }
     }
     return ok;
     };
     const chained = firestoreSyncQueueRef.current.catch(() => false).then(() => runTask());
     firestoreSyncQueueRef.current = chained;
     return chained;
  };
  const getApiEndpoints = (path: string): string[] => {
     const savedCustomServer = (localStorage.getItem('grid_notepad_custom_server') || '').trim();
     const customEndpoint = savedCustomServer ? `${savedCustomServer.replace(/\/$/, '')}${path}` : '';
     if (Capacitor.isNativePlatform()) {
        const devOrigin = `https://ais-dev-dva77knoqcna5xt4l6qx7i-4359193177.europe-west1.run.app${path}`;
        const preOrigin = `https://ais-pre-dva77knoqcna5xt4l6qx7i-4359193177.europe-west1.run.app${path}`;
        return Array.from(new Set([customEndpoint, preOrigin, devOrigin].filter(Boolean)));
     }
     const currentOrigin = typeof window !== 'undefined' && window.location && window.location.origin && window.location.origin.startsWith('http')
       ? window.location.origin
       : '';
     const relativePath = path;
     const fullCurrentOrigin = currentOrigin ? `${currentOrigin}${path}` : '';
     return Array.from(new Set([customEndpoint, relativePath, fullCurrentOrigin].filter(Boolean)));
  };
  const offloadDocsMediaToServerChunks = async (docsInput: GridDocument[], idToken: string | null): Promise<GridDocument[]> => {
     if (!Array.isArray(docsInput) || !idToken) return docsInput;
     const SRV_MEDIA_PREFIX = '__srvmedia__:';
     const CHUNK_SIZE = 2000000; // ~2MB chars per request — well below Cloud Run 32MB limit
     const endpoints = getApiEndpoints('/api/cloud/media/chunk');
     let activeEndpoint = endpoints[0] || '/api/cloud/media/chunk';
     const resultDocs: GridDocument[] = [];
     for (const docObj of docsInput) {
        if (!docObj || !Array.isArray(docObj.rows)) {
           resultDocs.push(docObj);
           continue;
        }
        let docModified = false;
        const nextRows: GridRow[] = [];
        for (let rIdx = 0; rIdx < docObj.rows.length; rIdx++) {
           let row = docObj.rows[rIdx];
           if (!row || typeof row !== 'object') {
              nextRows.push(row);
              continue;
           }
           for (const kind of ['image', 'audio', 'pdf'] as const) {
              const val = row[kind];
              if (typeof val === 'string' && val.length > 1500000 && !val.startsWith(SRV_MEDIA_PREFIX) && !val.startsWith('__fschunk__:')) {
                 const mediaId = `${String(docObj.id || 'doc').replace(/[^a-zA-Z0-9_\-]/g, '_').slice(0, 28)}_${String(row.id || `r${rIdx}`).replace(/[^a-zA-Z0-9_\-]/g, '_').slice(0, 28)}_${kind}_${val.length}`;
                 const cacheKey = `${mediaId}:${val.slice(0, 48)}:${val.slice(-24)}`;
                 let uploaded = uploadedServerMediaMapRef.current.get(cacheKey) === mediaId;
                 if (!uploaded) {
                    const totalChunks = Math.ceil(val.length / CHUNK_SIZE);
                    let allChunksOk = true;
                    for (let ci = 0; ci < totalChunks; ci++) {
                       const chunkSlice = val.slice(ci * CHUNK_SIZE, (ci + 1) * CHUNK_SIZE);
                       let chunkSent = false;
                       const orderedEps = [activeEndpoint, ...endpoints.filter((e) => e !== activeEndpoint)];
                       for (const ep of orderedEps) {
                          try {
                             const res = await fetch(ep, {
                                method: 'POST',
                                headers: {
                                   'Content-Type': 'application/json',
                                   'Authorization': `Bearer ${idToken}`,
                                },
                                body: JSON.stringify({
                                   mediaId,
                                   chunkIndex: ci,
                                   totalChunks,
                                   data: chunkSlice,
                                }),
                             });
                             if (res.ok && (res.headers.get('content-type') || '').includes('application/json')) {
                                const j = await res.json();
                                if (j?.success) {
                                   activeEndpoint = ep;
                                   chunkSent = true;
                                   break;
                                }
                             }
                          } catch {}
                       }
                       if (!chunkSent) {
                          allChunksOk = false;
                          break;
                       }
                    }
                    if (allChunksOk) {
                       uploadedServerMediaMapRef.current.set(cacheKey, mediaId);
                       uploaded = true;
                    }
                 }
                 if (uploaded) {
                    row = { ...row, [kind]: `${SRV_MEDIA_PREFIX}${mediaId}` };
                    docModified = true;
                 }
              }
           }
           nextRows.push(row);
        }
        resultDocs.push(docModified ? { ...docObj, rows: nextRows } : docObj);
     }
     return resultDocs;
  };
  const fetchSingleServerMediaById = async (mediaId: string, idToken: string | null): Promise<string | null> => {
     if (!mediaId || !idToken) return null;
     const cleanId = encodeURIComponent(mediaId.replace(/^__srvmedia__:/, ''));
     const endpoints = getApiEndpoints(`/api/cloud/media/${cleanId}?chunkIndex=0&chunkSize=2500000`);
     for (const ep of endpoints) {
        try {
           const firstRes = await fetch(ep, { headers: { 'Authorization': `Bearer ${idToken}` } });
           if (!firstRes.ok || !(firstRes.headers.get('content-type') || '').includes('application/json')) continue;
           const firstJson = await firstRes.json();
           if (!firstJson?.success || typeof firstJson.data !== 'string') continue;
           const totalChunks = Number(firstJson.totalChunks) || 1;
           if (totalChunks === 1) return firstJson.data;
           const parts: string[] = new Array(totalChunks);
           parts[0] = firstJson.data;
           const baseEp = ep.replace(/chunkIndex=0/, '');
           for (let ci = 1; ci < totalChunks; ci++) {
              const chunkEp = ep.replace('chunkIndex=0', `chunkIndex=${ci}`);
              const r = await fetch(chunkEp, { headers: { 'Authorization': `Bearer ${idToken}` } });
              if (!r.ok) return null;
              const j = await r.json();
              if (!j?.success || typeof j.data !== 'string') return null;
              parts[ci] = j.data;
           }
           void baseEp;
           return parts.join('');
        } catch {}
     }
     return null;
  };
  const hydrateServerMediaRefs = async (docsInput: GridDocument[], idToken: string | null): Promise<GridDocument[]> => {
     if (!Array.isArray(docsInput) || !idToken) return docsInput;
     const SRV_MEDIA_PREFIX = '__srvmedia__:';
     const needsHydration = docsInput.some(
        (d) => Array.isArray(d?.rows) && d.rows.some(
           (r: any) =>
              (typeof r?.image === 'string' && r.image.startsWith(SRV_MEDIA_PREFIX)) ||
              (typeof r?.audio === 'string' && r.audio.startsWith(SRV_MEDIA_PREFIX)) ||
              (typeof r?.pdf === 'string' && r.pdf.startsWith(SRV_MEDIA_PREFIX))
        )
     );
     if (!needsHydration) return docsInput;
     const resolvedCache = new Map<string, string>();
     const outDocs: GridDocument[] = [];
     for (const d of docsInput) {
        if (!d || !Array.isArray(d.rows)) {
           outDocs.push(d);
           continue;
        }
        let changed = false;
        const nextRows: GridRow[] = [];
        for (const r of d.rows) {
           let nextRow = r;
           for (const kind of ['image', 'audio', 'pdf'] as const) {
              const val = nextRow?.[kind];
              if (typeof val === 'string' && val.startsWith(SRV_MEDIA_PREFIX)) {
                 const mediaId = val.slice(SRV_MEDIA_PREFIX.length);
                 let fullData = resolvedCache.get(mediaId) || null;
                 if (!fullData) {
                    fullData = await fetchSingleServerMediaById(mediaId, idToken);
                    if (fullData) resolvedCache.set(mediaId, fullData);
                 }
                 if (fullData) {
                    nextRow = { ...nextRow, [kind]: fullData };
                    changed = true;
                 }
              }
           }
           nextRows.push(nextRow);
        }
        outDocs.push(changed ? { ...d, rows: nextRows } : d);
     }
     return outDocs;
  };
  useEffect(() => {
     const updateLogs = () => {
         try {
             setDebugLogs(JSON.parse(localStorage.getItem('grid_notepad_debug_logs') || '[]'));
         } catch(e){}
     };
     window.addEventListener('debug-log-updated', updateLogs);
     updateLogs();
     return () => window.removeEventListener('debug-log-updated', updateLogs);
  }, []);
  const [userGeminiKey, setUserGeminiKey] = useState<string>(() => localStorage.getItem('grid_notepad_gemini_key') || '');
  const [showKeyConfig, setShowKeyConfig] = useState<boolean>(false);
  const [isAiThinking, setIsAiThinking] = useState(false);
