  const [listeningCell, setListeningCell] = useState<{rIndex: number, colKey: string} | null>(null);
  const recognitionRef = useRef<any>(null);
  const toggleVoiceRecording = (rIndex: number, colKey: string) => {
     if (listeningCell && listeningCell.rIndex === rIndex && listeningCell.colKey === colKey) {
        // Stop listening
        if (recognitionRef.current) recognitionRef.current.stop();
        setListeningCell(null);
        showToast(t("Dëgjimi u ndal", "Listening stopped"));
        return;
     }
     if (recognitionRef.current) recognitionRef.current.stop();
     const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
     if (!SpeechRecognition) {
        showToast(t("Shfletuesi juaj nuk e suporton Voice-to-Text.", "Your browser does not support Voice-to-Text."));
        return;
     }
     const recognition = new SpeechRecognition();
     recognition.lang = dateLocale;
     recognition.continuous = false;
     recognition.interimResults = false;
     recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        lastUserTypingTsRef.current = Date.now();
        const baseRows = latestRowsRef.current.length > 0 ? latestRowsRef.current : rows;
        let newRows = [...baseRows];
        const currentVal = (newRows[rIndex]?.[colKey as keyof GridRow] as string) || '';
        newRows[rIndex] = { ...newRows[rIndex], [colKey]: (currentVal + (currentVal ? ' ' : '') + transcript).trim() };
        latestRowsRef.current = newRows;
        setRows(newRows);
        updateActiveDocumentState(latestTitleRef.current || title, newRows, latestHeadersRef.current.length > 0 ? latestHeadersRef.current : headers);
        showToast(t("Teksti u shtua!", "Text added!"));
        setListeningCell(null);
     };
     recognition.onerror = (event: any) => {
        if (event.error !== 'aborted' && event.error !== 'no-speech' && event.error !== 'not-allowed') {
            console.error("Speech recognition error", event.error);
        } else {
            console.warn("Speech recognition notice:", event.error);
        }
        if (event.error === 'not-allowed') {
           showToast(t("Ju lutem lejoni përdorimin e mikrofonit.", "Please allow microphone access."));
        } else if (event.error !== 'aborted' && event.error !== 'no-speech') {
           showToast(t("Gabim në dëgjim.", "Listening error."));
        }
        setListeningCell(null);
     };
     recognition.onend = () => {
        setListeningCell(null);
     };
     recognitionRef.current = recognition;
     recognition.start();
     setListeningCell({ rIndex, colKey });
     showToast(t("Po dëgjojmë... Flisni tani.", "Listening... Speak now."));
  };
  const [listeningModal, setListeningModal] = useState(false);
  const recognitionModalRef = useRef<any>(null);
