  useEffect(() => {
     if (isFirestorePausedNow()) {
       return;
     }
     if (typeof navigator !== 'undefined' && !navigator.onLine) {
       return;
     }
     let cancelled = false;
     async function testFirestoreConnection() {
       try {
         await resumeFirestoreNetwork();
         await getDocFromServer(doc(db, 'test', 'connection'));
       } catch (error) {
         if (cancelled) return;
         if (isFirestoreQuotaError(error)) {
           tripFirestoreQuotaCooldown(false);
           return;
         }
         if (error instanceof Error && error.message.includes('the client is offline')) {
           if (typeof navigator !== 'undefined' && !navigator.onLine) {
             return;
           }
           await new Promise((resolve) => setTimeout(resolve, 1500));
           if (cancelled || (typeof navigator !== 'undefined' && !navigator.onLine) || isFirestorePausedNow()) {
             return;
           }
           try {
             await resumeFirestoreNetwork();
             await getDocFromServer(doc(db, 'test', 'connection'));
           } catch (retryError) {
             if (cancelled) return;
             if (isFirestoreQuotaError(retryError)) {
               tripFirestoreQuotaCooldown(false);
               return;
             }
             if (retryError instanceof Error && retryError.message.includes('the client is offline')) {
               console.error("Please check your Firebase configuration.");
             }
           }
         }
       }
     }
     testFirestoreConnection();
     return () => {
       cancelled = true;
     };
  }, []);
  useEffect(() => {
     if (user) {
         const fetchCloudSettings = async () => {
            try {
               if (isFirestorePausedNow()) {
                  return;
               }
               if (hasPendingSync()) {
                  appendDebugLog(`⏳ [Settings Load] Ka ndryshime lokale në pritje; ruhen të dhënat lokale.`);
                  return;
               }
               const fsData = await fetchFirestoreSnapshot();
               const data = fsData.settings;
               if (data) {
                  const localTime = getLocalSettingsUpdatedAt() ? new Date(getLocalSettingsUpdatedAt()).getTime() : 0;
                  const remoteTime = data.settingsUpdatedAt ? new Date(data.settingsUpdatedAt).getTime() : 0;
                  if (localTime > 0 && remoteTime > 0 && localTime > remoteTime) {
                     appendDebugLog(`⏳ [Settings Load] Cilësimet lokale janë më të reja se Cloud.`);
                     return;
                  }
                  appendDebugLog(`🔒 [Settings Load] U gjetën cilësimet e sigurisë në Firestore!`);
                  if (data.blueText !== undefined) {
                     setBlueText(data.blueText);
                     latestBlueTextRef.current = data.blueText;
                     localStorage.setItem('grid_notepad_blue', data.blueText);
                  }
                  if (data.secretList) {
                     setSecretList(data.secretList);
                     latestSecretListRef.current = data.secretList;
                     localStorage.setItem('grid_notepad_secret_list', JSON.stringify(data.secretList));
                  }
                  if (data.pin) {
                     localStorage.setItem('grid_notepad_pin', data.pin);
                  }
                  if (data.gistToken) {
                     setGistToken(data.gistToken);
                     localStorage.setItem('grid_notepad_gist_token', data.gistToken);
                  }
                  if (data.gistId) {
                     setGistId(data.gistId);
                     localStorage.setItem('grid_notepad_gist_id', data.gistId);
                  }
                  if (data.geminiKey) {
                     setUserGeminiKey(data.geminiKey);
                     localStorage.setItem('grid_notepad_gemini_key', data.geminiKey);
                  }
                  if (Array.isArray(data.customLabels)) {
                     const mergedLbls = Array.from(new Set([...latestCustomLabelsRef.current, ...data.customLabels]));
                     setCustomLabels(mergedLbls);
                     latestCustomLabelsRef.current = mergedLbls;
                     localStorage.setItem('customLabels', JSON.stringify(mergedLbls));
                  }
                  if (Array.isArray(data.trashItems)) {
                     const mergedTrash = mergeTrashItems(latestTrashItemsRef.current, data.trashItems, getPendingTrashDeletes());
                     setTrashItems(mergedTrash);
                     latestTrashItemsRef.current = mergedTrash;
                     localStorage.setItem(TRASH_ITEMS_KEY, JSON.stringify(mergedTrash));
                  }
                  if (Array.isArray(data.padNotes)) {
                     const mergedPads = mergePadNotesList(latestPadNotesRef.current, data.padNotes);
                     setPadNotes(mergedPads);
                     latestPadNotesRef.current = mergedPads;
                     try {
                        localStorage.setItem('grid_notepad_pads_v1', JSON.stringify(mergedPads));
                     } catch {}
                  }
                  if (data.notesColor !== undefined) {
                     setNotesColor(data.notesColor);
                     latestNotesColorRef.current = data.notesColor;
                     localStorage.setItem('grid_notepad_notes_color', data.notesColor);
                  }
                  if (data.textColorMode !== undefined) {
                     setTextColorMode(data.textColorMode);
                     latestTextColorModeRef.current = data.textColorMode;
                     localStorage.setItem('grid_notepad_text_color_mode', data.textColorMode);
                  }
                  if (typeof data.textSize === 'number') {
                     setTextSize(data.textSize);
                     latestTextSizeRef.current = data.textSize;
                     localStorage.setItem('grid_notepad_text_size', String(data.textSize));
                  }
                  if (typeof data.textWeight === 'number') {
                     setTextWeight(data.textWeight);
                     latestTextWeightRef.current = data.textWeight;
                     localStorage.setItem('grid_notepad_text_weight', String(data.textWeight));
                  }
                  if (data.settingsUpdatedAt) {
                     localStorage.setItem(SETTINGS_UPDATED_AT_KEY, data.settingsUpdatedAt);
                  }
               }
            } catch (err) {
               console.error("Error loading settings from Firestore:", err);
            }
         };
         fetchCloudSettings();
         const fetchCloudData = async () => {
           try {
               if (isFirestoreQuotaPaused()) return;
               if (hasPendingSync() || Date.now() - lastUserTypingTsRef.current < 15000) return;
               const pendingDeletes = getPendingDeletes();
               const fsSnap = await fetchFirestoreSnapshot();
               if (isFirestoreQuotaPaused()) return;
               if (hasPendingSync() || Date.now() - lastUserTypingTsRef.current < 15000) return;
               const fetched: GridDocument[] = fsSnap.docs.filter(d => d && !pendingDeletes.includes(d.id));
               let needsUpload = pendingDeletes.length > 0 || hasPendingSync();
               
               setDocuments(prevLocal => {
                   const mergedMap = new Map<string, GridDocument>();
                   prevLocal.forEach(d => {
                       if (d && d.id && !pendingDeletes.includes(d.id)) mergedMap.set(d.id, d);
                   });
                   
                   fetched.forEach(d => {
                       const existing = mergedMap.get(d.id);
                       if (!existing || new Date(d.updatedAt || 0) > new Date(existing.updatedAt || 0)) {
                           mergedMap.set(d.id, d);
                       }
                   });
                   
                   const newMerged = Array.from(mergedMap.values()).sort((a, b) => new Date(b.updatedAt || 0).getTime() - new Date(a.updatedAt || 0).getTime());
                   latestDocsRef.current = newMerged;
                   saveDocsLocalSafe(newMerged);
                   
                   const currActiveId = activeDocIdRef.current;
                   if (currActiveId && Date.now() - lastUserTypingTsRef.current >= 15000) {
                       const currentViewingDoc = newMerged.find(x => x.id === currActiveId);
                       const oldViewingDoc = prevLocal.find(x => x.id === currActiveId);
                       if (currentViewingDoc && oldViewingDoc && currentViewingDoc.updatedAt !== oldViewingDoc.updatedAt) {
                           setTimeout(() => {
                               window.dispatchEvent(new CustomEvent('cloud-doc-updated', { detail: currentViewingDoc }));
                           }, 10);
                       }
                   }
                   newMerged.forEach(docObj => {
                       const cloudVersion = fetched.find(c => c.id === docObj.id);
                       if (!cloudVersion || new Date(docObj.updatedAt || 0) > new Date(cloudVersion.updatedAt || 0)) {
                           needsUpload = true;
                       }
                   });
                   return newMerged;
               });
               if (needsUpload && navigator.onLine && !onlineViewRef.current) {
                   setTimeout(() => {
                       syncWithGoogleCloud(
                           latestDocsRef.current,
                           true,
                           latestBlueTextRef.current,
                           latestSecretListRef.current,
                           latestCustomLabelsRef.current,
                           getPendingDeletes(),
                           latestNotesColorRef.current,
                           latestTrashItemsRef.current
                       );
                   }, 200);
               }
           } catch (err) {
               console.error("Auto sync fetch error", err);
           }
         };
         fetchCloudData();
     }
  }, [user]);
  // Periodic Auto-Backup to LocalStorage
