  const triggerPhoneDeviceSecurityCheck = async () => {
      setDeviceVaultModal(prev => ({
          ...prev,
          status: 'verifying',
          errorMsg: '',
      }));
      const res = await requestPhoneDeviceSecurityVerification(language);
      if (res.verified) {
          setDeviceVaultModal(prev => ({
              ...prev,
              status: 'unlocked',
              verifiedMethod: res.method,
              errorMsg: '',
          }));
          showToast(t('🔓 Leja e sigurisë u aprovua! Kyçat u shfaqën në Show View.', '🔓 Device security approved! Keys unlocked in Show View.'));
          return;
      }
      if (res.reason === 'blocked' || res.reason === 'unsupported') {
          setDeviceVaultModal(prev => ({
              ...prev,
              status: 'fallback_verify',
              errorMsg: res.message,
              deviceLockInput: '',
              patternNodes: [],
          }));
          return;
      }
      setDeviceVaultModal(prev => ({
          ...prev,
          status: 'gate',
          errorMsg: res.message,
      }));
  };
  const completeFallbackDeviceVerification = () => {
      const { lockType, deviceLockInput, patternNodes } = deviceVaultModal;
      if (lockType === 'pin') {
          if (!/^\d{4,12}$/.test(deviceLockInput.trim())) {
              setDeviceVaultModal(prev => ({ ...prev, errorMsg: t('Vendosni PIN-in e telefonit (minimumi 4 shifra).', 'Enter phone PIN (minimum 4 digits).') }));
              return;
          }
      } else if (lockType === 'password') {
          if (deviceLockInput.trim().length < 4) {
              setDeviceVaultModal(prev => ({ ...prev, errorMsg: t('Vendosni Password-in e telefonit (minimumi 4 karaktere).', 'Enter phone Password (minimum 4 characters).') }));
              return;
          }
      } else if (lockType === 'pattern') {
          if (patternNodes.length < 4) {
              setDeviceVaultModal(prev => ({ ...prev, errorMsg: t('Lidhni të paktën 4 pika për Pattern-in e telefonit.', 'Connect at least 4 dots for the phone Pattern.') }));
              return;
          }
      }
      const methodLabelMap = {
          biometric: t('Gjurmë Gishti / Biometri e Pajisjes', 'Device Fingerprint / Biometrics'),
          pin: t('PIN i Sigurisë së Telefonit', 'Phone Security PIN'),
          password: t('Password i Sigurisë së Telefonit', 'Phone Security Password'),
          pattern: t('Pattern (Model) i Telefonit', 'Phone Security Pattern'),
      };
      setDeviceVaultModal(prev => ({
          ...prev,
          status: 'unlocked',
          verifiedMethod: methodLabelMap[lockType],
          errorMsg: '',
          deviceLockInput: '',
          patternNodes: [],
      }));
      showToast(t('🔓 Verifikimi i sigurisë u krye! Show View është hapur.', '🔓 Security verification passed! Show View is open.'));
  };
