  const handleImportCalendarBackupJson = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      e.target.value = '';
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
          try {
              const parsed = JSON.parse(String(reader.result || '{}'));
              const incoming: CalendarEvent[] = Array.isArray(parsed)
                  ? parsed
                  : Array.isArray(parsed?.events)
                    ? parsed.events
                    : [];
              if (incoming.length === 0) {
                  showToast(t('Skedari nuk përmban takime të vlefshme.', 'No valid events found in file.'));
                  return;
              }
              const existingIds = new Set(calendarEvents.map((ev) => ev.id));
              const merged = [...calendarEvents];
              let added = 0;
              incoming.forEach((ev) => {
                  if (ev && ev.id && ev.title && ev.date && !existingIds.has(ev.id)) {
                      merged.push(ev);
                      added++;
                  }
              });
              saveCalendarEventsList(merged);
              if (parsed?.settings && typeof parsed.settings === 'object') {
                  saveCalendarSettingsObj({ ...calendarSettings, ...parsed.settings });
              }
              showToast(t(`✓ U importuan ${added} takime në Kalendar!`, `✓ Imported ${added} events to Calendar!`));
          } catch {
              showToast(t('Skedari JSON i Kalendarit nuk është i vlefshëm.', 'Invalid Calendar JSON file.'));
          }
      };
      reader.readAsText(file);
  };
  const handleExportCalendarToNoteDoc = (scope: 'today' | 'all') => {
      const todayYmd = getLocalYmd(new Date());
      const source = scope === 'today'
          ? calendarEvents.filter((ev) => eventMatchesDate(ev, selectedCalendarDate))
          : calendarEvents;
      if (source.length === 0) {
          showToast(t('Nuk ka takime për t’i kthyer në shënim.', 'No events to export as a note.'));
          return;
      }
      const sorted = [...source].sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
      const nowIso = new Date().toISOString();
      const docTitle = scope === 'today'
          ? `📅 ${t('Axhenda', 'Agenda')} · ${selectedCalendarDate}`
          : `📅 ${t('Raport i Plotë Kalendari', 'Full Calendar Report')} (${todayYmd})`;
      const reportRows: GridRow[] = [
          { id: `row-${Date.now()}-0`, status: 'none', image: '' },
          ...sorted.map((ev, idx) => ({
              id: `row-${Date.now()}-${idx + 1}`,
              status: ev.completed ? ('ok' as const) : ev.category === 'emergjent' ? ('x' as const) : ('blue' as const),
              col1: `${ev.date} ${ev.time}`,
              col2: ev.title,
              col3: ev.notes || '-',
              col4: ev.completed ? t('Kryer', 'Done') : (ev.alarmEnabled ? `🔔 ${t('Me Zile', 'Alarm')}` : t('Aktiv', 'Active')),
          })),
      ];
      const newDoc: GridDocument = {
          id: `doc-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
          title: docTitle,
          headers: [t('Data & Ora', 'Date & Time'), t('Takimi / Shënimi', 'Appointment'), t('Detaje', 'Notes'), t('Statusi', 'Status')],
          columnWidths: [145, 200, 230, 120],
          rows: reportRows,
          tags: [t('Kalendar', 'Calendar')],
          createdAt: nowIso,
          updatedAt: nowIso,
      };
      const updatedDocs = [newDoc, ...documents];
      setDocuments(updatedDocs);
      latestDocsRef.current = updatedDocs;
      saveDocsLocalSafe(updatedDocs);
      triggerAutoSave(updatedDocs, true);
      setShowCalendarModal(false);
      openDocument(newDoc);
      showToast(t(`✓ U krijua shënimi "${docTitle}" me ${sorted.length} takime!`, `✓ Created "${docTitle}" with ${sorted.length} events!`));
  };
  const requestCalendarNotificationPermission = async () => {
      const nb3 = (window as any)?.NB3Device;
      // 1. Native Android APK bridge (handles Android 13+ POST_NOTIFICATIONS + NotificationManager)
      if (nb3 && typeof nb3.requestNotificationPermission === 'function') {
          try {
              const alreadyGranted = typeof nb3.hasNotificationPermission === 'function' ? nb3.hasNotificationPermission() : false;
              const waitNativePerm = alreadyGranted
                  ? Promise.resolve(true)
                  : new Promise<boolean>((resolve) => {
                        let settled = false;
                        const timer = setTimeout(() => {
                            if (!settled) {
                                settled = true;
                                window.removeEventListener('nb3-notif-permission', handler as EventListener);
                                resolve(Boolean(nb3.hasNotificationPermission?.()));
                            }
                        }, 12000);
                        const handler = (ev: CustomEvent<{ granted?: boolean }>) => {
                            if (!settled) {
                                settled = true;
                                clearTimeout(timer);
                                window.removeEventListener('nb3-notif-permission', handler as EventListener);
                                resolve(Boolean(ev?.detail?.granted));
                            }
                        };
                        window.addEventListener('nb3-notif-permission', handler as EventListener);
                        nb3.requestNotificationPermission();
                    });
              const granted = await waitNativePerm;
              if (granted) {
                  setNotifPermState('granted');
                  saveCalendarSettingsObj({ ...calendarSettings, notificationsEnabled: true });
                  nb3.showLocalNotification?.(
                      t('🔔 NoteBook3 · Njoftimet Aktive', '🔔 NoteBook3 · Notifications Active'),
                      t('Leja e njoftimeve të sistemit u aktivizua me sukses!', 'System notification permission is now active!')
                  );
                  void playCalendarAlarmTone('chime');
                  showToast(t('✓ Leja e njoftimeve të sistemit u aktivizua me sukses!', '✓ System notification permission enabled!'));
              } else {
                  setNotifPermState('denied');
                  showToast(t('Leja u refuzua. Aktivizojeni te Cilësimet > Aplikacionet > NoteBook3 > Njoftimet.', 'Permission denied. Enable it in Settings > Apps > NoteBook3 > Notifications.'));
              }
              return;
          } catch {
              showToast(t('Nuk u hap kërkesa native e njoftimeve.', 'Could not open native notification request.'));
              return;
          }
      }

      // 2. Web / PWA Notification API
      if (typeof Notification === 'undefined') {
          setNotifPermState('unsupported');
          saveCalendarSettingsObj({ ...calendarSettings, notificationsEnabled: true });
          void playCalendarAlarmTone('chime');
          showToast(t('🔔 Alarmet me zë dhe vibrim brenda NoteBook3 janë aktive!', '🔔 In-app sound & vibration alarms are active!'));
          return;
      }
      try {
          const currentPerm = Notification.permission;
          const perm = currentPerm === 'granted' ? 'granted' : await Notification.requestPermission();
          setNotifPermState(perm);
          if (perm === 'granted') {
              saveCalendarSettingsObj({ ...calendarSettings, notificationsEnabled: true });
              try {
                  new Notification(t('🔔 NoteBook3 · Njoftimet Aktive', '🔔 NoteBook3 · Notifications Active'), {
                      body: t('Njoftimet dhe zilet e Kalendarit janë gati!', 'Calendar notifications and alarms are ready!'),
                  });
              } catch {}
              void playCalendarAlarmTone('chime');
              showToast(t('✓ Njoftimet e sistemit u aktivizuan (u dërgua njoftim prove)!', '✓ System notifications enabled (test alert sent)!'));
          } else {
              const inIframe = window.self !== window.top;
              showToast(
                  inIframe
                      ? t('Dritarja preview bllokon popup-et e shfletuesit; zilet me audio punojnë normalisht brenda aplikacionit.', 'Preview frame blocks browser popups; in-app audio alarms work normally.')
                      : t('Leja e njoftimeve është e bllokuar në shfletues. Aktivizojeni te ikona e kyçit (Permissions), ose përdorni alarmin me zë.', 'Browser notifications are blocked. Allow them in site permissions, or use in-app audio alarms.')
              );
          }
      } catch {
          showToast(t('Nuk u hap kërkesa e njoftimeve; zilet brenda aplikacionit janë aktive.', 'Could not request notifications; in-app alarms remain active.'));
      }
  };
