  const autopilotTimeout = useRef<any>(null);
  const runAiAutopilot = (updatedDocs?: GridDocument[], updatedBlueText?: string) => {
     const isEnabled = localStorage.getItem('grid_ai_autopilot') === 'true';
     if (!isEnabled || !navigator.onLine) return;
     if (autopilotTimeout.current) clearTimeout(autopilotTimeout.current);
     autopilotTimeout.current = setTimeout(async () => {
        setIsAiAutopilotRunning(true);
        appendDebugLog(`🤖 [AI Autopilot] Agjenti aktiv po analizon ndryshimet e fundit në sfond...`);
        try {
           const docs = updatedDocs || latestDocsRef.current || documents;
           const finalBlueText = updatedBlueText !== undefined ? updatedBlueText : blueText;
           const docsForAi = docs.map(docItem => {
              const filledRows = docItem.rows.filter(r =>
                 docItem.headers.some((_, ci) => String(r[`col${ci + 1}`] || '').trim() !== '') ||
                 (r.status && r.status !== 'none')
              ).map(r => {
                 const compactRow: any = { id: r.id };
                 if (r.status && r.status !== 'none') compactRow.status = r.status;
                 docItem.headers.forEach((_, ci) => {
                    const k = `col${ci + 1}`;
                    const v = r[k];
                    if (v !== undefined && v !== null && String(v).trim() !== '') compactRow[k] = String(v);
                 });
                 return compactRow;
              });
              return {
                 id: docItem.id,
                 title: docItem.title,
                 headers: docItem.headers,
                 tags: docItem.tags,
                 rows: filledRows
              };
           });
           
           const mail = (email || localStorage.getItem('grid_notepad_saved_email') || '').trim();
           const payload = JSON.stringify({ 
              prompt: "Autopilot Check: Kontrollo dhe auto-përditëso/korrigjo llogaritjet, plotëso kolonat totale/shuma të zbrazëta ose korrigjo drejtshkrimin nëse ka gabime të dukshme.", 
              documents: docsForAi, 
              activeDocId: activeDocIdRef.current, 
              image: null, 
              audio: null,
              blueText: finalBlueText,
               secretList,
               userEmail: mail,
               geminiKey: userGeminiKey || localStorage.getItem('grid_notepad_gemini_key') || '',
               isBackgroundAutopilot: true
           });
           
           const endpoints = getApiEndpoints('/api/ai/chat');
           let response: Response | null = null;
           for (const ep of endpoints) {
              try {
                 const res = await fetch(ep, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: payload
                 });
                 if (res.ok && res.headers.get('content-type')?.includes('application/json')) {
                    response = res;
                    break;
                 }
              } catch (e) {}
           }
           if (response) {
              const data = await response.json();
              if (data && data.actions && Array.isArray(data.actions) && data.actions.length > 0) {
                 appendDebugLog(`🎉 [AI Autopilot] Agjenti gjeti korrigjime dhe po i aplikon ato automatikisht!`);
                 data.actions.forEach((act: any) => {
                     if (act.type === 'PROPOSE_COLUMNS_CHANGE' && act.documentId) {
                         setDocuments(prevDocs => {
                             const next = prevDocs.map(d => {
                                 if (d.id === act.documentId) {
                                     return {
                                         ...d,
                                         headers: act.newHeaders || d.headers,
                                         columnWidths: act.newColumnWidths || d.columnWidths,
                                         rows: act.newRows || d.rows,
                                         updatedAt: new Date().toISOString()
                                     };
                                 }
                                 return d;
                             });
                             saveDocsLocalSafe(next);
                             syncWithGoogleCloud(next, true);
                             return next;
                         });
                         if (act.documentId === activeDocIdRef.current && Date.now() - lastUserTypingTsRef.current >= 15000) {
                             if (act.newHeaders) setHeaders(act.newHeaders);
                             if (act.newColumnWidths) setColumnWidths(act.newColumnWidths);
                             if (act.newRows) setRows(act.newRows);
                         }
                         showToast(t("⚡ Agjenti Gemini kreu auto-përditësime në sfond!", "⚡ Gemini agent applied background updates!"));
                     } else if (act.type === 'UPDATE_DOCUMENT_ROWS' && act.documentId) {
                         setDocuments(prevDocs => {
                             const next = prevDocs.map(d => {
                                 if (d.id === act.documentId) {
                                     return {
                                         ...d,
                                         rows: act.newRows || d.rows,
                                         updatedAt: new Date().toISOString()
                                     };
                                 }
                                 return d;
                             });
                             saveDocsLocalSafe(next);
                             syncWithGoogleCloud(next, true);
                             return next;
                         });
                         if (act.documentId === activeDocIdRef.current && act.newRows && Date.now() - lastUserTypingTsRef.current >= 15000) {
                             setRows(act.newRows);
                         }
                         showToast(t("⚡ Agjenti Gemini korrigjoi rreshtat e bllokut automatikisht!", "⚡ Gemini agent updated list rows automatically!"));
                     } else if (act.type === 'DELETE_DOCUMENT' && act.documentId) {
                         const targetDoc = latestDocsRef.current.find(d => d.id === act.documentId);
                         const nextTrash = targetDoc ? appendItemsToTrashState([buildTrashFromDoc(targetDoc)]) : latestTrashItemsRef.current;
                         const next = latestDocsRef.current.filter(d => d.id !== act.documentId);
                         setDocuments(next);
                         latestDocsRef.current = next;
                         saveDocsLocalSafe(next);
                         markPendingSync([act.documentId]);
                         syncWithGoogleCloud(next, true, undefined, undefined, undefined, [act.documentId], undefined, nextTrash);
                         if (act.documentId === activeDocIdRef.current) {
                             setActiveDocId(null);
                         }
                         showToast(t(
                             `⚡ Autopilot fshiu dhe ruajti te Kosh-i dokumentin: ${act.title || act.documentId}`,
                             `⚡ Autopilot moved document to Trash: ${act.title || act.documentId}`
                         ));
                     }
                 });
              } else {
                 appendDebugLog(`🤖 [AI Autopilot] Analiza mbaroi: Nuk u gjet asnjë gabim apo boshllëk për të plotësuar.`);
              }
           }
        } catch (err: any) {
           console.warn("Autopilot error:", err);
        } finally {
           setIsAiAutopilotRunning(false);
        }
     }, 10000); // 10 seconds of inactivity triggers the background agent
  };
  const triggerAutoSave = (updatedDocs: GridDocument[], immediate = false) => {
      latestDocsRef.current = updatedDocs;
      pendingLocalSaveRef.current = true;
      markPendingSync();
      
      setAutoSaveMsg(t('Duke u ruajtur...', 'Saving...'));
      
      if (localSaveTimeout.current) clearTimeout(localSaveTimeout.current);
      if (immediate) {
          saveDocsLocalSafe(updatedDocs);
          pendingLocalSaveRef.current = false;
      } else {
          localSaveTimeout.current = setTimeout(() => {
              saveDocsLocalSafe(updatedDocs);
              pendingLocalSaveRef.current = false;
              const freqCheck = parseInt(localStorage.getItem('grid_cloud_sync_freq') || '500', 10);
              if (freqCheck === -1 || !navigator.onLine) {
                 setAutoSaveMsg(t('U ruajt lokalisht', 'Saved locally'));
                 setTimeout(() => setAutoSaveMsg(''), 1500);
              }
          }, 250);
      }

      const freq = parseInt(localStorage.getItem('grid_cloud_sync_freq') || '500', 10);
      if (freq === -1) return; // Off
      setIsSaving(true);
      
      if (autoSaveTimeout.current) clearTimeout(autoSaveTimeout.current);
      const delay = immediate ? 0 : Math.min(freq, 800);
      autoSaveTimeout.current = setTimeout(async () => {
         if (navigator.onLine) {
            await syncWithGoogleCloud(
               latestDocsRef.current,
               true,
               latestBlueTextRef.current,
               latestSecretListRef.current,
               latestCustomLabelsRef.current,
               getPendingDeletes(),
               latestNotesColorRef.current,
               latestTrashItemsRef.current
            );
         } else {
            setIsSaving(false);
            setAutoSaveMsg(t('Lokalisht (Do ngarkohet online)', 'Saved locally (Queued for online)'));
            setTimeout(() => setAutoSaveMsg(''), 2000);
         }
      }, delay);
      runAiAutopilot(updatedDocs);
  };
