    const savedLabels = JSON.parse(localStorage.getItem('customLabels') || '[]');
    const savedSecrets = JSON.parse(localStorage.getItem('grid_notepad_secret_list') || '[]');
    const savedTrash = JSON.parse(localStorage.getItem(TRASH_ITEMS_KEY) || '[]');
    const savedBlue = localStorage.getItem('grid_notepad_blue') || '';
