    const newHeaders = Array.from({ length: colCount }, (_, idx) => `${t('Kolona', 'Column')} ${idx + 1}`);
    const isAutoMode = defaultNewDocRowMode === 'auto';
    const newRows = getEmptyRows(isAutoMode ? 1 : defaultNewDocRows);
    
    clearDocHistory();
    setRowFilter('all');
    setDocSearch('');
