  const importLocalBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
     const file = e.target.files?.[0];
     if (!file) return;
     
     const reader = new FileReader();
     reader.onload = (event) => {
        try {
           const content = event.target?.result as string;
           const parsed = JSON.parse(content);
           
           let docsToSet: GridDocument[] = [];
           let labelsToSet: string[] = [];
           
           if (Array.isArray(parsed)) {
              docsToSet = parsed;
           } else if (parsed && typeof parsed === 'object') {
              if (Array.isArray(parsed.documents)) {
                 docsToSet = parsed.documents;
              }
              if (Array.isArray(parsed.customLabels)) {
                 labelsToSet = parsed.customLabels;
              }
              if (Array.isArray(parsed.trashItems)) {
                 const restoredTrash = sanitizeTrashItems(parsed.trashItems);
                 setTrashItems(restoredTrash);
                 latestTrashItemsRef.current = restoredTrash;
                 localStorage.setItem(TRASH_ITEMS_KEY, JSON.stringify(restoredTrash));
              }
              if (parsed.blueText !== undefined) {
                 setBlueText(parsed.blueText);
                 latestBlueTextRef.current = parsed.blueText;
                 localStorage.setItem('grid_notepad_blue', parsed.blueText);
              }
              if (Array.isArray(parsed.secretList)) {
                 setSecretList(parsed.secretList);
                 latestSecretListRef.current = parsed.secretList;
                 localStorage.setItem('grid_notepad_secret_list', JSON.stringify(parsed.secretList));
              }
              if (Array.isArray(parsed.padNotes)) {
                 const restoredPads = mergePadNotesList(latestPadNotesRef.current, parsed.padNotes);
                 setPadNotes(restoredPads);
                 latestPadNotesRef.current = restoredPads;
                 try {
                    localStorage.setItem('grid_notepad_pads_v1', JSON.stringify(restoredPads));
                 } catch {}
              }
              if (parsed.notesColor !== undefined) {
                 setNotesColor(parsed.notesColor);
                 latestNotesColorRef.current = parsed.notesColor;
                 localStorage.setItem('grid_notepad_notes_color', parsed.notesColor);
              }
              if (parsed.textColorMode !== undefined) {
                 setTextColorMode(parsed.textColorMode);
                 latestTextColorModeRef.current = parsed.textColorMode;
                 localStorage.setItem('grid_notepad_text_color_mode', parsed.textColorMode);
              }
           }
           
           if (docsToSet.length > 0 && docsToSet[0].id && docsToSet[0].rows) {
              if (labelsToSet.length > 0) {
                 setCustomLabels(labelsToSet);
                 latestCustomLabelsRef.current = labelsToSet;
                 localStorage.setItem('customLabels', JSON.stringify(labelsToSet));
              }
              markSettingsUpdated();
              setDocuments(docsToSet);
              latestDocsRef.current = docsToSet;
              triggerAutoSave(docsToSet, true);
              
              showToast(t("Të dhënat u rikthyen me sukses dhe po sinkronizohen!", "Data restored successfully and syncing!"));
              setBackupModal(false);
           } else {
              showToast(t("Skedari nuk është i vlefshëm për këtë aplikacion.", "This file is not valid for this app."));
           }
        } catch(err) {
           showToast(t("Skedari i dëmtuar ose i pavlefshëm.", "Corrupted or invalid file."));
        }
     };
     reader.readAsText(file);
     e.target.value = ''; // reset
  };
  const forceCloudBackup = async (silent = false) => {
    setIsSaving(true);
    if (!silent) setAutoSaveMsg(t('Po ngarkon në Cloud & Firebase...', 'Uploading to Cloud & Firebase...'));
    const docsToPush = latestDocsRef.current.length > 0 ? latestDocsRef.current : documents;
    const blueToPush = latestBlueTextRef.current;
    const secretsToPush = latestSecretListRef.current;
    const labelsToPush = mergeAllLabels(latestCustomLabelsRef.current, [], docsToPush);
    const trashToPush = latestTrashItemsRef.current;
    const notesColorToPush = latestNotesColorRef.current;
    const textColorToPush = latestTextColorModeRef.current;

    const success = await syncWithGoogleCloud(
       docsToPush,
       silent,
       blueToPush,
       secretsToPush,
       labelsToPush,
       getPendingDeletes(),
       notesColorToPush,
       trashToPush
    );

    const activeToken = gistToken || localStorage.getItem('grid_notepad_gist_token');
    const activeGist = gistId || localStorage.getItem('grid_notepad_gist_id');
    let gistFirstTimeOk = false;
    if (activeToken && !activeGist && navigator.onLine) {
       gistFirstTimeOk = await saveToGist(docsToPush, true, blueToPush, secretsToPush, labelsToPush, notesColorToPush, textColorToPush, trashToPush);
    }

    setIsSaving(false);
    if (success || gistFirstTimeOk) {
        localStorage.setItem('grid_notepad_last_backup_at', new Date().toISOString());
        setAutoSaveMsg(t('Ngarkuar!', 'Uploaded!'));
        if (!silent) {
           showToast(t(
               `☁️ Backup u ngarkua: ${docsToPush.length} lista, ${labelsToPush.length} etiketa, ${secretsToPush.length} sekrete, ${trashToPush.length} në kosh!`,
               `☁️ Backup uploaded: ${docsToPush.length} lists, ${labelsToPush.length} labels, ${secretsToPush.length} secrets, ${trashToPush.length} in trash!`
           ));
        }
    } else {
        setAutoSaveMsg(t('Lokal!', 'Local!'));
    }
    setTimeout(() => setAutoSaveMsg(''), 3000);
    return success || gistFirstTimeOk;
  };
  const handleManualGistBackup = async (silent = false) => {
    setIsSaving(true);
    if (!silent) setAutoSaveMsg(t('Po ngarkon në Gist...', 'Uploading to Gist...'));
    const docsToPush = latestDocsRef.current.length > 0 ? latestDocsRef.current : documents;
    const blueToPush = latestBlueTextRef.current;
    const secretsToPush = latestSecretListRef.current;
    const labelsToPush = mergeAllLabels(latestCustomLabelsRef.current, [], docsToPush);
    const trashToPush = latestTrashItemsRef.current;
    const notesColorToPush = latestNotesColorRef.current;
    const textColorToPush = latestTextColorModeRef.current;

    const gistOk = await saveToGist(
       docsToPush,
       silent,
       blueToPush,
       secretsToPush,
       labelsToPush,
       notesColorToPush,
       textColorToPush,
       trashToPush
    );

    if (gistOk) {
       setOnlineBlueText(blueToPush);
       setOnlineSecretList(secretsToPush);
       setOnlineCustomLabels(labelsToPush);
       setOnlineTrashItems(trashToPush);
       setOnlineNotesColor(notesColorToPush);
       localStorage.setItem('grid_notepad_last_backup_at', new Date().toISOString());
       if (user && navigator.onLine) {
          syncWithGoogleCloud(docsToPush, true, blueToPush, secretsToPush, labelsToPush, getPendingDeletes(), notesColorToPush, trashToPush).catch(console.error);
       }
    }
    setIsSaving(false);
    setAutoSaveMsg(gistOk ? t('Ngarkuar në Gist!', 'Uploaded to Gist!') : t('Gabim!', 'Error!'));
    setTimeout(() => setAutoSaveMsg(''), 3000);
    return gistOk;
  };
