  const handleCapitalizeTitles = () => {
       executeProtectedAction(() => {
           const nowIso = new Date().toISOString();
           const newDocs = documents.map(d => {
               const docTitle = d.title;
               const newTitle = docTitle.charAt(0).toUpperCase() + docTitle.slice(1);
               return { ...d, title: newTitle, updatedAt: nowIso };
           });
           setDocuments(newDocs);
           latestDocsRef.current = newDocs;
           saveDocsLocalSafe(newDocs);
           triggerAutoSave(newDocs, true);
           showToast(t("Titujt u kapitalizuan me sukses.", "Titles capitalized successfully."));
       });
       setShowOptionsMenu(false);
  };
  const handleRemoveAllRowStatuses = () => {
       executeProtectedAction(() => {
           let statusesRemoved = 0;
           const nowIso = new Date().toISOString();
           const newDocs = documents.map(d => {
               let changed = false;
               const cleanRows = d.rows.map(r => {
                   if (r.status !== 'none' && r.status !== 'lock') {
                       statusesRemoved++;
                       changed = true;
                       return { ...r, status: 'none' };
                   }
                   return r;
               });
               return changed ? { ...d, rows: cleanRows, updatedAt: nowIso } : d;
           });
           if (statusesRemoved > 0) {
               setDocuments(newDocs);
               latestDocsRef.current = newDocs;
               saveDocsLocalSafe(newDocs);
               triggerAutoSave(newDocs, true);
               showToast(t(`U fshinë ${statusesRemoved} statuse ngjyrash nga rrjeshtat.`, `Removed ${statusesRemoved} row color statuses.`));
           } else {
               showToast(t("Nuk kishte asnjë status rrjeshti për të fshirë.", "No row statuses found to remove."));
           }
       });
       setShowOptionsMenu(false);
  };
  const handleDeleteEmptyDocs = () => {
       executeProtectedAction(async () => {
           let emptyCount = 0;
           const emptyDocIds: string[] = [];
           const emptyDocs: GridDocument[] = [];
           const newDocs = documents.filter(d => {
               const hasData = d.rows.some(r => d.headers.some((_, c) => (r[`col${c+1}`] || '').toString().trim()) || r.image || r.audio);
               if (!hasData) {
                   emptyCount++;
                   emptyDocIds.push(d.id);
                   emptyDocs.push(d);
               }
               return hasData;
           });
           if (emptyCount > 0) {
               const nextTrash = appendItemsToTrashState(emptyDocs.map(buildTrashFromDoc));
               setDocuments(newDocs);
               latestDocsRef.current = newDocs;
               saveDocsLocalSafe(newDocs);
               setCloudDocs(prev => prev.filter(d => !emptyDocIds.includes(d.id)));
               markPendingSync(emptyDocIds);
               if (navigator.onLine) {
                   await syncWithGoogleCloud(newDocs, true, undefined, undefined, undefined, emptyDocIds, undefined, nextTrash);
               }
               showToast(t(`U fshinë me sukses ${emptyCount} dokumente bosh (u ruajtën te Kosh-i online).`, `Deleted ${emptyCount} empty documents (saved to online Trash).`));
           } else {
               showToast(t("Nuk u gjetën dokumente bosh.", "No empty documents found."));
           }
       });
       setShowOptionsMenu(false);
  };
  const handleCleanupEmptyRowsAll = () => {
       executeProtectedAction(async () => {
           let totalCleaned = 0;
           const nowIso = new Date().toISOString();
           const newDocs = documents.map(d => {
               const originalLen = d.rows.length;
               const cleanRows = d.rows.filter(r => d.headers.some((_, c) => (r[`col${c+1}`] || '').toString().trim()) || r.image || r.audio);
               const diff = originalLen - cleanRows.length;
               totalCleaned += diff;
               return diff > 0 ? { ...d, rows: cleanRows, updatedAt: nowIso } : d;
           });
           if (totalCleaned > 0) {
               setDocuments(newDocs);
               latestDocsRef.current = newDocs;
               saveDocsLocalSafe(newDocs);
               setCloudDocs(prev => prev.map(c => {
                   const local = newDocs.find(l => l.id === c.id);
                   return local ? { ...c, rows: local.rows, updatedAt: local.updatedAt } : c;
               }));
               triggerAutoSave(newDocs, true);
               showToast(t(`U pastruan ${totalCleaned} rrjeshta bosh kudo.`, `Cleaned ${totalCleaned} empty rows everywhere.`));
           } else {
               showToast(t("Nuk kishte asnjë rrjesht bosh për t'u pastruar.", "No empty rows found to clean."));
           }
       });
       setShowOptionsMenu(false);
  };
  const handleStripAllImages = () => {
       executeProtectedAction(() => {
           setConfirmDialog({
               isOpen: true,
               title: t('Fshi të gjitha imazhet?', 'Delete all images?'),
               message: t(
                   'Kujdes! Dëshironi të fshini të gjitha imazhet nga aplikacioni për të kursyer hapësirën (Storage)? Kjo nuk zhbëhet!',
                   'Warning! Do you want to remove all images from the app to save storage space? This cannot be undone!'
               ),
               confirmLabel: t('Fshi imazhet', 'Delete Images'),
               danger: true,
               onConfirm: async () => {
                   let imagesRemoved = 0;
                   const nowIso = new Date().toISOString();
                   const currentDocs = latestDocsRef.current.length > 0 ? latestDocsRef.current : documents;
                   const newDocs = currentDocs.map(d => {
                       let changed = false;
                       const cleanRows = d.rows.map(r => {
                           if (r.image) {
                               imagesRemoved++;
                               changed = true;
                           }
                           return { ...r, image: null, imageName: '' };
                       });
                       return changed ? { ...d, rows: cleanRows, updatedAt: nowIso } : d;
                   });
                   if (imagesRemoved > 0) {
                       setDocuments(newDocs);
                       latestDocsRef.current = newDocs;
                       saveDocsLocalSafe(newDocs);
                       setCloudDocs(prev => prev.map(c => {
                           const local = newDocs.find(l => l.id === c.id);
                           return local ? { ...c, rows: local.rows, updatedAt: local.updatedAt } : c;
                       }));
                       triggerAutoSave(newDocs, true);
                       showToast(t(`U fshinë me sukses ${imagesRemoved} imazhe.`, `Successfully deleted ${imagesRemoved} images.`));
                   } else {
                       showToast(t("Asnjë imazh nuk u gjet.", "No images found."));
                   }
               }
           });
       });
       setShowOptionsMenu(false);
  };
