                         const savedFbPwd = localStorage.getItem('grid_notepad_saved_pwd') || '';
                         const savedGistToken = gistToken || localStorage.getItem('grid_notepad_gist_token') || '';
                         const savedGistId = gistId || localStorage.getItem('grid_notepad_gist_id') || '';

